#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to hold section information for each thread
typedef struct {
    int* array;  // Pointer to the array
    int start;   // Start index of the section
    int end;     // End index of the section
} ThreadArgs;

// Bubble sort algorithm
void bubbleSort(int* array, int size) {
    int i, j;
    for (i = 0; i < size - 1; i++) {
        for (j = 0; j < size - i - 1; j++) {
            if (array[j] > array[j + 1]) {
                // Swap elements
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

// Thread function to sort a section of the array
void* threadSort(void* arg) {
    ThreadArgs* threadArgs = (ThreadArgs*)arg;
    bubbleSort(threadArgs->array + threadArgs->start, threadArgs->end - threadArgs->start + 1);
    pthread_exit(NULL);
}

// Function to merge two sorted sections
void mergeSections(int* array, int start, int mid, int end) {
    int* merged = (int*)malloc((end - start + 1) * sizeof(int));
    int i = start, j = mid + 1, k = 0;

    while (i <= mid && j <= end) {
        if (array[i] <= array[j]) {
            merged[k++] = array[i++];
        } else {
            merged[k++] = array[j++];
        }
    }

    while (i <= mid) {
        merged[k++] = array[i++];
    }

    while (j <= end) {
        merged[k++] = array[j++];
    }

    for (i = start, k = 0; i <= end; i++, k++) {
        array[i] = merged[k];
    }

    free(merged);
}

// Function to recursively merge sections until one large sorted section is obtained
void mergeSortSections(int* array, int start, int end) {
    if (start < end) {
        int mid = (start + end) / 2;
        mergeSortSections(array, start, mid);
        mergeSortSections(array, mid + 1, end);
        mergeSections(array, start, mid, end);
    }
}

int main() {
    // Open the input file
    FILE* file = fopen("numbers.dat", "r");
    if (file == NULL) {
        printf("Error opening file.");
        return 1;
    }

    // Read the numbers into an array
    int* numbers = (int*)malloc(1000000 * sizeof(int));
    for (int i = 0; i < 1000000; i++) {
        fscanf(file, "%d", &numbers[i]);
    }
    fclose(file);

    // Create an array of thread IDs
    pthread_t threads[10];

    // Create 10 threads for sorting sections of the array
    for (int i = 0; i < 10; i++) {
        ThreadArgs* args = (ThreadArgs*)malloc(sizeof(ThreadArgs));
        args->array = numbers;
        args->start = i * 100000;
        args->end = (i + 1) * 100000 - 1;
        pthread_create(&threads[i], NULL, threadSort, (void*)args);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Merge the sorted sections recursively
    mergeSortSections(numbers, 0, 999999);

    // Open the output file
    file = fopen("sorted_numbers.dat", "w");
    if (file == NULL) {
        printf("Error opening file.");
        return 1;
    }

    // Write the sorted numbers to the output file
    for (int i = 0; i < 1000000; i++) {
        fprintf(file, "%d\n", numbers[i]);
    }
    fclose(file);

    // Free memory
    free(numbers);

    // Verify the output file is sorted
    system("sort -c sorted_numbers.dat");

    return 0;
}
