import java.util.Arrays;

abstract class Vectors {

}

interface Arithmetic<E> {
    E add(E other);
}

class SimpleVec2D extends Vectors implements Arithmetic<SimpleVec2D> {
    private double x;
    private double y;

    public SimpleVec2D(double x, double y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public SimpleVec2D add(SimpleVec2D other) {
        double newX = this.x + other.x;
        double newY = this.y + other.y;
        return new SimpleVec2D(newX, newY);
    }

    @Override
    public int hashCode() {
        double distance = Math.sqrt(x * x + y * y);
        return (int) (distance % 5);
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

class SimpleTable {
    private SimpleVec2D[][] theTable;

    public SimpleTable() {
        theTable = new SimpleVec2D[5][0];
    }

    public void addElement(SimpleVec2D vector) {
        int hashCode = vector.hashCode();
        theTable[hashCode] = Arrays.copyOf(theTable[hashCode], theTable[hashCode].length + 1);
        SimpleVec2D[] row = theTable[hashCode];
        System.arraycopy(row, 0, row, 1, row.length - 1);
        row[0] = vector;
    }

    public SimpleVec2D sumElement() {
        SimpleVec2D sum = new SimpleVec2D(0, 0);
        for (SimpleVec2D[] row : theTable) {
            for (SimpleVec2D vector : row) {
                sum = sum.add(vector);
            }
        }
        return sum;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < theTable.length; i++) {
            sb.append("[").append(i).append("] : ");
            for (SimpleVec2D vector : theTable[i]) {
                sb.append(vector).append(" | ");
            }
            sb.append("\n");
        }
        return sb.toString();
    }
}

public class Main {
    public static void main(String[] args) {
        SimpleTable table = new SimpleTable();

        for (int i = 0; i < 10; i++) {
            double x = Math.random() * 10;
            double y = Math.random() * 10;
            SimpleVec2D vector = new SimpleVec2D(x, y);
            table.addElement(vector);
            System.out.println(vector + " Dist = " + Math.sqrt(x * x + y * y) + ", HashCode = " + vector.hashCode());
