        System.out.println("SUM = " + sum + " Dist = " + Math.sqrt(sum.x * sum.x + sum.y * sum.y));
        System.out.println("SUM - First = " + sum.add(((SimpleVec2D[]) table.theTable[4])[0].add(sum.negate())) + " Dist = " + Math.sqrt(sum.x * sum.x + sum.y * sum.y));
    }
}
