chrome.browserAction.onClicked.addListener(() => {
  // Get user input (API URL, request method, request body, headers, and dynamic property)
  const apiUrl = prompt("Enter API URL");
  const requestMethod = prompt("Enter Request Method (GET/POST/PUT/DELETE)");
  const requestBody = prompt("Enter Request Body (optional)");
  const headers = JSON.parse(prompt("Enter Headers (in JSON format)"));
  const dynamicProperty = prompt("Enter Property to Change Dynamically");

  // Initial request parameters
  let currentPage = 0;
  let nextPageUrl = null;

  // Fetch images function
  const fetchImages = () => {
    const url = nextPageUrl || apiUrl;

    fetch(url, {
      method: requestMethod,
      body: requestBody || undefined,
      headers,
    })
      .then((response) => response.json())
      .then((data) => {
        // Get image URLs from the API response based on the JSON structure
        const imageUrls = data.images.map((image) => image[dynamicProperty]);

        // Create a new tab to display the gallery
        chrome.tabs.create({ url: chrome.runtime.getURL("gallery.html") }, (tab) => {
          // Pass the image URLs to the gallery tab
          chrome.tabs.sendMessage(tab.id, { imageUrls });
        });

        // Check if pagination is available
        if (data.nextPageUrl) {
          currentPage++;
          nextPageUrl = data.nextPageUrl;
        } else {
          currentPage = 0;
          nextPageUrl = null;
        }
      })
      .catch((error) => {
        console.error("Error fetching images:", error);
      });
  };

  // Initial image fetching
  fetchImages();

  // Listen for next page requests
  chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
    if (message === "nextPage") {
      fetchImages();
    }
  });
});
