    public ModeSetting rotationModeSetting = new ModeSetting("Мод Ротации", "Matrix", "Matrix", "Sunrise");
    public SliderSetting attackDistanceSetting = new SliderSetting("Дистанция", 3.3f, .0f, 15.0f, 0.01f);
