import org.hibernate.dialect.Dialect;
import org.hibernate.dialect.SQLiteDialect;
import org.hibernate.type.AbstractSingleColumnStandardBasicType;
import org.hibernate.type.BasicTypeRegistry;
import org.hibernate.type.Type;
import org.hibernate.type.descriptor.sql.SqlTypeDescriptor;

public class SQLiteDialectWithLocalDateTime extends SQLiteDialect {

    private final Type localDateTimeType;

    public SQLiteDialectWithLocalDateTime() {
        this.localDateTimeType = new LocalDateTimeType();
    }

    @Override
    public Type getHibernateType(int code) {
        if (code == Types.TIMESTAMP) {
            return localDateTimeType;
        }
        return super.getHibernateType(code);
    }

    // Register the custom type for TIMESTAMP
    @Override
    protected void registerColumnType(int code, String name) {
        if (code == Types.TIMESTAMP) {
            registerColumnType(code, name, localDateTimeType.getSqlTypeDescriptor());
        } else {
            super.registerColumnType(code, name);
        }
    }

    // Helper method to register the custom type correctly
    private void registerColumnType(int code, String name, SqlTypeDescriptor sqlTypeDescriptor) {
        final BasicTypeRegistry typeRegistry = getBasicTypeRegistry();
        final Type oldType = typeRegistry.getRegisteredType(code);
        if (oldType != null) {
            typeRegistry.unregister(oldType);
        }
        typeRegistry.register(new AbstractSingleColumnStandardBasicType<>(sqlTypeDescriptor, localDateTimeType.getJavaTypeDescriptor()) {
            @Override
            public String getName() {
                return name;
            }
        }, code);
    }
}
