			float distanceBetweenCameraAndGrenade = Vector3.Distance(cameraPosition, launchPoint.position);
			Vector3 shootPosition = cameraPosition + cameraLookDirection * distanceBetweenCameraAndGrenade;

			if (Raycast(shootPosition, cameraLookDirection, out var hit))
