				Vector3 obstacle2 = CheckObstacles();
				targetSphere.transform.position = obstacle2 != Vector3.zero ? obstacle2 : hit.point;

				RenderLaunch(launchPoint.position, hit.point);

				srTrajectoryPredictor.enabled = true;
