```php
function generateColorGradient($color1, $color2, $steps) {
    // Parse color values
    $color1 = sscanf($color1, "#%2x%2x%2x");
    $color2 = sscanf($color2, "#%2x%2x%2x");

    // Calculate step size for each color channel
    $stepR = ($color2[0] - $color1[0]) / $steps;
    $stepG = ($color2[1] - $color1[1]) / $steps;
    $stepB = ($color2[2] - $color1[2]) / $steps;

    // Generate gradient colors
    $gradient = [];
    for ($i = 0; $i <= $steps; $i++) {
        $r = $color1[0] + ($stepR * $i);
        $g = $color1[1] + ($stepG * $i);
        $b = $color1[2] + ($stepB * $i);
        $gradient[] = sprintf("#%02x%02x%02x", $r, $g, $b);
    }

    return $gradient;
}

// Usage example
$color1 = "#FF0000"; // Red
$color2 = "#0000FF"; // Blue
$steps = 10;         // Number of steps in gradient

$gradient = generateColorGradient($color1, $color2, $steps);

// Output gradient colors
foreach ($gradient as $color) {
    echo "<div style='background-color: $color; width: 50px; height: 50px;'></div>";
}
```

