function generateColorGradient($startColor, $endColor, $steps) {
    $startColorRgb = sscanf($startColor, "#%2x%2x%2x");
    $endColorRgb = sscanf($endColor, "#%2x%2x%2x");

    $gradient = [];

    for ($i = 0; $i <= $steps; $i++) {
        $ratio = $i / $steps;

        $r = round($startColorRgb[0] * (1 - $ratio) + $endColorRgb[0] * $ratio);
        $g = round($startColorRgb[1] * (1 - $ratio) + $endColorRgb[1] * $ratio);
        $b = round($startColorRgb[2] * (1 - $ratio) + $endColorRgb[2] * $ratio);

        $gradient[] = sprintf("#%02x%02x%02x", $r, $g, $b);
    }

    return $gradient;
}

