```php
<?php
// Define start and end colors (RGB format)
$startColor = array(255, 0, 0); // Red
$endColor = array(0, 0, 255); // Blue

// Define the number of steps (more steps = smoother gradient)
$steps = 10;

// Calculate the color increment
