for ($i = 0; $i <= $steps; $i++) {
    $color = array();
    for ($j = 0; $j < 3; $j++) {
        $color[$j] = intval($startColor[$j] + ($increment[$j] * $i));
    }
    $gradientColors[] = $color;
}

// Print the gradient colors
foreach ($gradientColors as $color) {
    $rgb = implode(',', $color);
    echo '<span style="background-color: rgb(' . $rgb . '); width: 50px; height: 50px; display: inline-block;"></span>';
}
?>
```

