                if (event.key.keysym.sym == SDLK_f) {
                    if (!isFullscreen) {
                        SDL_SetWindowFullscreen(window, SDL_WINDOW_FULLSCREEN);  // Enable fullscreen mode
                    }
                    else {
                        SDL_SetWindowFullscreen(window, 0);  // Disable fullscreen mode
                    }

                    isFullscreen = !isFullscreen;
                }
            }
            else if (event.type == SDL_WINDOWEVENT) {
                if (event.window.event == SDL_WINDOWEVENT_FULLSCREEN && event.window.windowID == SDL_GetWindowID(window)) {
                    if (event.window.data1 == 1) {
                        printf("Window fullscreened\n");
                    }
                    else {
                        printf("Window unfullscreened\n");
                    }
                }
            }
        }

        SDL_RenderClear(renderer);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyWindow(window);
    SDL_DestroyRenderer(renderer);
    SDL_Quit();

    return 0;
}
```

