```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Text.RegularExpressions;

class WildberriesParser
{
    static void Main(string[] args)
    {
        // Вводите URL страницы с товарами Wildberries
        string url = "https://www.wildberries.ru/catalog/obuv/zhenskaya";

        // Загрузка HTML-страницы
        string html = DownloadHtml(url);

        // Парсинг товаров
        List<string> products = ParseProducts(html);

        // Вывод результатов
        foreach (string product in products)
        {
            Console.WriteLine(product);
        }

        Console.ReadLine();
    }

    static string DownloadHtml(string url)
    {
        WebClient client = new WebClient();
        Stream data = client.OpenRead(url);
        StreamReader reader = new StreamReader(data);
        string html = reader.ReadToEnd();
        data.Close();
        reader.Close();
        return html;
    }

    static List<string> ParseProducts(string html)
    {
        List<string> products = new List<string>();

        // Паттерн для поиска информации о товарах
        string pattern = @"<a class=""ref_goods_n_p j-open-full-product-card""[^>]*?>(.*?)<\/a>";

        // Применение регулярного выражения к HTML-строке
        MatchCollection matches = Regex.Matches(html, pattern);

        foreach (Match match in matches)
        {
            // Извлечение информации о товаре
            string product = match.Groups[1].Value;
            products.Add(product);
        }

        return products;
    }
}
```

