В `Controllers` создайте новый класс `ProductController.cs` со следующим содержимым:

```csharp
using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;

namespace YourAPI.Controllers
{
    [ApiController]
    [Route("[controller]")]
    public class ProductController : ControllerBase
    {
        private List<Product> _products;

        public ProductController()
        {
            // Инициализация списка продуктов
            _products = new List<Product>
            {
                new Product { Id = 1, Name = "Product 1", Price = 10.99 },
                new Product { Id = 2, Name = "Product 2", Price = 15.99 },
                new Product { Id = 3, Name = "Product 3", Price = 20.99 }
            };
        }

        [HttpGet]
        public ActionResult<IEnumerable<Product>> Get()
        {
            // Возвращает все продукты
            return Ok(_products);
        }

        [HttpGet("{id}")]
        public ActionResult<Product> Get(int id)
        {
            // Возвращает продукт с указанным ID
            var product = _products.Find(p => p.Id == id);
            if (product == null)
            {
                return NotFound();
            }
            return Ok(product);
        }

        [HttpPost]
        public ActionResult<Product> Post(Product product)
        {
            // Добавляет новый продукт
            _products.Add(product);
            return CreatedAtAction(nameof(Get), new { id = product.Id }, product);
        }

        [HttpPut("{id}")]
        public IActionResult Put(int id, Product product)
        {
            // Обновляет продукт с указанным ID
            var existingProduct = _products.Find(p => p.Id == id);
            if (existingProduct == null)
            {
                return NotFound();
            }

            existingProduct.Name = product.Name;
            existingProduct.Price = product.Price;
            return NoContent();
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(int id)
        {
            // Удаляет продукт с указанным ID
            var product = _products.Find(p => p.Id == id);
            if (product == null)
            {
                return NotFound();
            }
            _products.Remove(product);
            return NoContent();
        }
    }

    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public double Price { get; set; }
    }
}
```

В этом примере мы создали контроллер `ProductController`, который предоставляет REST API для управления продуктами. Все действия (GET, POST, PUT, DELETE) выполняются над списком продуктов, которые представлены классом `Product`. `ProductController` находится в маршруте `/product`.

