#include <iostream>
#include <cmath>

// Class representing the real part of a complex number
class Real {
private:
    double value;

public:
    Real(double val) : value(val) {}

    // Addition operator
    Real operator+(const Real& other) const {
        return Real(value + other.value);
    }

    // Subtraction operator
    Real operator-(const Real& other) const {
        return Real(value - other.value);
    }

    // Multiplication operator
    Real operator*(const Real& other) const {
        return Real(value * other.value);
    }

    // Division operator
    Real operator/(const Real& other) const {
        return Real(value / other.value);
    }

    // Modulus function
    double modulus() const {
        return std::abs(value);
    }

    // Square root function
    Real sqrt() const {
        return Real(std::sqrt(value));
    }

    // Getter for the value
    double getValue() const {
        return value;
    }
};

// Class representing the imaginary part of a complex number
class Imaginary {
private:
    double value;

public:
    Imaginary(double val) : value(val) {}

    // Addition operator
    Imaginary operator+(const Imaginary& other) const {
        return Imaginary(value + other.value);
    }

    // Subtraction operator
    Imaginary operator-(const Imaginary& other) const {
        return Imaginary(value - other.value);
    }

    // Multiplication operator
    Imaginary operator*(const Imaginary& other) const {
        return Imaginary(value * other.value);
    }

    // Division operator
    Imaginary operator/(const Imaginary& other) const {
        return Imaginary(value / other.value);
    }

    // Modulus function
    double modulus() const {
        return std::abs(value);
    }

    // Square root function
    Imaginary sqrt() const {
        return Imaginary(std::sqrt(value));
    }

    // Getter for the value
    double getValue() const {
        return value;
    }
};

// Class representing a complex number
class Complex {
private:
    Real real;
    Imaginary imaginary;

public:
    Complex(const Real& r, const Imaginary& i) : real(r), imaginary(i) {}

    // Addition operator
    Complex operator+(const Complex& other) const {
        return Complex(real + other.real, imaginary + other.imaginary);
    }

    // Subtraction operator
    Complex operator-(const Complex& other) const {
        return Complex(real - other.real, imaginary - other.imaginary);
    }

    // Multiplication operator
    Complex operator*(const Complex& other) const {
        return Complex((real * other.real) - (imaginary * other.imaginary),
                       (real * other.imaginary) + (other.real * imaginary));
    }

    // Division operator
    Complex operator/(const Complex& other) const {
        double divisor = (other.real.getValue() * other.real.getValue()) + (other.imaginary.getValue() * other.imaginary.getValue());
        double realPart = ((real.getValue() * other.real.getValue()) + (imaginary.getValue() * other.imaginary.getValue())) / divisor;
        double imagPart = ((imaginary.getValue() * other.real.getValue()) - (real.getValue() * other.imaginary.getValue())) / divisor;
        return Complex(Real(realPart), Imaginary(imagPart));
    }

    // Modulus function
    double modulus() const {
        return std::sqrt((real.getValue() * real.getValue()) + (imaginary.getValue() * imaginary.getValue()));
    }

    // Square root function
    Complex sqrt() const {
        double mod = modulus();
        double realPart = std::sqrt((real.getValue() + mod) / 2);
        double imagPart = std::sqrt(((-1 * real.getValue()) + mod) / 2);
        return Complex(Real(realPart), Imaginary(imagPart));
    }

    // Getter for the real part
    Real getReal() const {
        return real;
    }

    // Getter for the imaginary part
    Imaginary getImaginary() const {
        return imaginary;
    }
};

int main() {
    // Example usage of the complex number library
    Real r1(2.5);
    Real r2(3.7);
    Imaginary i1(1.2);
    Imaginary i2(0.8);

    Complex c1(r1, i1);
    Complex c2(r2, i2);

    Complex sum = c1 + c2;
    Complex diff = c1 - c2;
    Complex prod = c1 * c2;
    Complex quot = c1 / c2;

    std::cout << "Sum: " << sum.getReal().getValue() << " + " << sum.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Difference: " << diff.getReal().getValue() << " + " << diff.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Product: " << prod.getReal().getValue() << " + " << prod.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Quotient: " << quot.getReal().getValue() << " + " << quot.getImaginary().getValue() << "i" << std::endl;

    double mod = c1.modulus();
    Complex sqrt = c1.sqrt();

    std::cout << "Modulus of c1: " << mod << std::endl;
    std::cout << "Square root of c1: " << sqrt.getReal().getValue() << " + " << sqrt.getImaginary().getValue() << "i" << std::endl;

    return 0;
}
```

This library defines three classes: `Real` (representing the real part of a complex number), `Imaginary` (representing the imaginary part of a complex number), and `Complex` (representing a complex number). The `Real` and `Imaginary` classes encapsulate the functionalities related to their respective parts, and the `Complex` class combines them to provide the necessary operations for complex number arithmetic.

In the example usage in the `main()` function, a couple of complex numbers are created (`c1` and `c2`), and various operations such as addition, subtraction, multiplication, division, modulus, and square root are performed on them. The results are then printed to the console.

