        friend Complex operator*(const Complex& c1, const Complex& c2);
        friend Complex operator/(const Complex& c1, const Complex& c2);
        friend Complex pow(const Complex& c, int exp);
        friend Complex root(const Complex& c, int n);

    public:
        Complex() {}
        Complex(double r, double i) : realPart(r), imaginaryPart(i) {}

        double getReal() const {
            return realPart.getReal();
        }

        void setReal(double r) {
            realPart.setReal(r);
        }

        double getImaginary() const {
            return imaginaryPart.getImaginary();
        }

        void setImaginary(double i) {
            imaginaryPart.setImaginary(i);
        }
    };

    static int counter = 0;

    static double calculateModulus(const Complex& c) {
        double real = c.realPart.getReal();
        double imaginary = c.imaginaryPart.getImaginary();
        return std::sqrt(real * real + imaginary * imaginary);
    }

    double modulus(const Complex& c) {
        return calculateModulus(c);
    }

    Complex operator+(const Complex& c1, const Complex& c2) {
        double real = c1.realPart.getReal() + c2.realPart.getReal();
        double imaginary = c1.imaginaryPart.getImaginary() + c2.imaginaryPart.getImaginary();
        return Complex(real, imaginary);
    }

    Complex operator-(const Complex& c1, const Complex& c2) {
        double real = c1.realPart.getReal() - c2.realPart.getReal();
        double imaginary = c1.imaginaryPart.getImaginary() - c2.imaginaryPart.getImaginary();
        return Complex(real, imaginary);
    }

    Complex operator*(const Complex& c1, const Complex& c2) {
        double real = c1.realPart.getReal() * c2.realPart.getReal() - c1.imaginaryPart.getImaginary() * c2.imaginaryPart.getImaginary();
        double imaginary = c1.realPart.getReal() * c2.imaginaryPart.getImaginary() + c1.imaginaryPart.getImaginary() * c2.realPart.getReal();
        return Complex(real, imaginary);
    }

    Complex operator/(const Complex& c1, const Complex& c2) {
        double divisor = c2.realPart.getReal() * c2.realPart.getReal() + c2.imaginaryPart.getImaginary() * c2.imaginaryPart.getImaginary();
        if (divisor == 0.0) {
            throw "Error: Division by zero!";
        }
        double real = (c1.realPart.getReal() * c2.realPart.getReal() + c1.imaginaryPart.getImaginary() * c2.imaginaryPart.getImaginary()) / divisor;
        double imaginary = (c1.imaginaryPart.getImaginary() * c2.realPart.getReal() - c1.realPart.getReal() * c2.imaginaryPart.getImaginary()) / divisor;
        return Complex(real, imaginary);
    }

    Complex pow(const Complex& c, int exp) {
        if (exp < 0) {
            throw "Error: Invalid exponent!";
        }
        double magnitude = calculateModulus(c);
        double argument = std::atan2(c.imaginaryPart.getImaginary(), c.realPart.getReal());
        double real = std::pow(magnitude, exp) * std::cos(exp * argument);
        double imaginary = std::pow(magnitude, exp) * std::sin(exp * argument);
        return Complex(real, imaginary);
    }

    Complex root(const Complex& c, int n) {
        if (n <= 0) {
            throw "Error: Invalid root order!";
        }
        double magnitude = calculateModulus(c);
        double argument = std::atan2(c.imaginaryPart.getImaginary(), c.realPart.getReal());
        double real = std::pow(magnitude, 1.0 / n) * std::cos(argument / n);
        double imaginary = std::pow(magnitude, 1.0 / n) * std::sin(argument / n);
        return Complex(real, imaginary);
    }
}  // namespace ComplexNumbers

int main() {
    ComplexNumbers::Complex c1(2.0, 3.0);
    ComplexNumbers::Complex c2(1.0, 2.0);

    ComplexNumbers::Complex sum = c1 + c2;
    ComplexNumbers::Complex difference = c1 - c2;
    ComplexNumbers::Complex product = c1 * c2;
    ComplexNumbers::Complex quotient = c1 / c2;
    double mod = ComplexNumbers::modulus(c1);
    ComplexNumbers::Complex power = ComplexNumbers::pow(c1, 3);
    ComplexNumbers::Complex root = ComplexNumbers::root(c1, 2);

    return 0;
}
```

