    const regex = /(?:[a-z0-9+!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*|"(?:[\x01-\x08\x0b\x0c\x0e-\x1f\x21\x23-\x5b\x5d-\x7f]|\\[\x01-\x09\x0b\x0c\x0e-\x7f])*")@(?:(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]*[a-z0-9])?|\[(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?|[a-z0-9-]*[a-z0-9]:(?:[\x01-\x08\x0b\x0c\x0e-\x1f\x21-\x5a\x53-\x7f]|\\[\x01-\x09\x0b\x0c\x0e-\x7f])+)\])/gi;

    // Recursive function to search for matching strings in the DOM
    function searchDOM(element, result) {
        element.childNodes.forEach(function(node) {
            if (node.nodeType === Node.TEXT_NODE) {
                // Find matching strings in the text node
                const matches = node.textContent.match(regex);
                if (matches && matches.length > 0) {
                    // Found matches, add to the result array
                    result.push(...matches);
                }
            } else if (node.nodeType === Node.ELEMENT_NODE) {
                // Recursively search child elements
                searchDOM(node, result);
            }
        });
    }

    // Start the search from the document's root element
    const result = [];
    searchDOM(document.documentElement, result);

    // Concatenate the matched strings with new lines
    const output = result.join('\n');

    // Output the concatenated strings to the console
    console.log(output);
})();
