  navMenu.classList.toggle('open');
});

// Like functionality for posts
const likeButtons = document.querySelectorAll('.post .like-button');

likeButtons.forEach(function(likeButton) {
  likeButton.addEventListener('click', function() {
    const post = likeButton.closest('.post');
    const likesCount = post.querySelector('.likes-count');
    let likes = parseInt(likesCount.textContent);

    if (likeButton.classList.contains('liked')) {
      likeButton.classList.remove('liked');
      likes--;
    } else {
      likeButton.classList.add('liked');
      likes++;
    }

    likesCount.textContent = likes;
  });
});
```

In this example, the JavaScript code adds two functionalities to your social media app:

1. Toggle Navigation Menu: When the user clicks on the navigation toggle button, the JavaScript code adds or removes the "open" class to the navigation menu, enabling or disabling its visibility on mobile screens.

2. Like Functionality for Posts: When the user clicks on any like button in a post, the JavaScript code finds the closest post element and updates the like count. If the like button is already marked as "liked," it removes the "liked" class and decreases the like count. If the like button is not marked as "liked," it adds the "liked" class and increases the like count.

