hook1 = (params, next) => {
    console.log('1')
    setTimeout(() => {
      console.log('1-1')
      next()
      console.log('1-2')
    }, 1000)
  }

  const hook2 = (params, next) => {
    console.log('2')
    next(false)
  }

  const hook3 = (params, next) => {
    console.log('3')
    next(false)
  }

  const runHooks = async (hooks, params, cb) => {

  }

  runHooks([hook1, hook2, hook3], {}, (result) => {
  console.log('done', result)
  })

  /* 输出顺序：
  1
  1-1 // 1s之后
  2
  done, false
  1-2
  */

补充的函数是runHooks函数，该函数用于依次执行hooks数组中的函数，并传递参数params给每个函数。最后通过回调函数cb返回执行结果。

具体实现如下：

```javascript
const runHooks = async (hooks, params, cb) => {
  const next = (result = true) => {
    const hook = hooks.shift()
    if (hook) {
      setTimeout(() => {
        hook(params, next)
      }, 0)
    } else {
      cb(result)
    }
  }
  next()
}
```

在runHooks函数内部，使用递归的方式依次执行hooks数组中的函数。通过调用next函数来执行下一个函数，如果没有下一个函数则执行回调函数。

需要注意的是，在next函数内部，使用setTimeout函数将执行下一个函数的操作放在事件循环队列的下一个tick中，这样确保了异步函数能够按照正确的顺序执行。

使用补充的runHooks函数执行示例代码：

```javascript
runHooks([hook1, hook2, hook3], {}, (result) => {
  console.log('done', result)
})
```

