    ADCSRA = 0b10000111;    // ADC enable, ADC prescaler = 128
}

uint16_t ADC_read() {
    ADCSRA |= (1 << ADSC);  // Start ADC conversion
    while (ADCSRA & (1 << ADSC));   // Wait for conversion to complete
    return ADC;             // Return ADC value
}

void LED_bar_graph(uint16_t value) {
    if (value < 341) {
        PORTD = 0b00000000;   // No LEDs turned on
    } else if (value < 682) {
        PORTD = 0b00000100;   // Only LED1 turned on
    } else if (value < 1023) {
        PORTD = 0b00000110;   // LED1 and LED2 turned on
    } else {
        PORTD = 0b00000111;   // All LEDs turned on
    }
}

