Here is a sample code in CUDA C++ for implementing bitonic sorting in a parallel manner:

```cpp
#include <stdio.h>

// Method to compare and swap elements based on direction
__device__ void swap(int *array, int i, int j, int direction) {
    if ((array[i] > array[j] && direction == 1) || (array[i] < array[j] && direction == 0)) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

// Bitonic merge kernel
__global__ void bitonicMerge(int *array, int length, int compareLength, int direction) {
    int i = threadIdx.x + blockIdx.x * blockDim.x;
    int step = compareLength / 2;

    if (i < length && (i / compareLength) % 2 == direction) {
        if ((i / step) % 2 == 0) {
            swap(array, i, i + step, direction);
        }
    }
}

// Bitonic sort kernel
__global__ void bitonicSort(int *array, int length, int compareLength, int direction) {
    int i = threadIdx.x + blockIdx.x * blockDim.x;
    int step = compareLength / 2;

    if (i < length) {
        for(int j = step; j > 0; j /= 2)
        {
            int k = i ^ j;

            if (k > i)
            {
                if ((i & compareLength) == 0) {
                    swap(array, i, k, direction);
                }
                else {
                    swap(array, i, k, !direction);
                }
            }

            __syncthreads();
        }
    }
}

// Function to perform bitonic sorting in parallel
void bitonicSortParallel(int *array, int length) {
    int *dev_array;

    int size = length * sizeof(int);

    cudaMalloc((void**)&dev_array, size);
    cudaMemcpy(dev_array, array, size, cudaMemcpyHostToDevice);

    dim3 blocksPerGrid(ceil(length / 256.0), 1, 1);
    dim3 threadsPerBlock(256, 1, 1);

    for (int compareLength = 2; compareLength <= length; compareLength *= 2) {
        for (int direction = 1; direction >= 0; direction--) {
            bitonicSort <<<blocksPerGrid, threadsPerBlock>>> (dev_array, length, compareLength, direction);
        }
    }

    cudaMemcpy(array, dev_array, size, cudaMemcpyDeviceToHost);
    cudaFree(dev_array);
}

// Sequential implementation of bitonic sorting
void bitonicSortSequential(int *array, int length) {
    for (int compareLength = 2; compareLength <= length; compareLength *= 2) {
        for (int direction = 1; direction >= 0; direction--) {
            for (int i = 0; i < length; i++) {
                if ((i & compareLength) == 0) {
                    for (int j = 0; j < compareLength / 2; j++) {
                        int k = i ^ (j << 1);
                        if (k < length) {
                            swap(array, i, k, direction);
                        }
                    }
                }
            }
        }
    }
}

int main() {
    int length = 16;
    int array[length] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Original Array:\n");
    for (int i = 0; i < length; i++) {
        printf("%d ", array[i]);
    }

    printf("\n\n");

    bitonicSortSequential(array, length);

    printf("Sequential Sorted Array:\n");
    for (int i = 0; i < length; i++) {
        printf("%d ", array[i]);
    }

    printf("\n\n");

    bitonicSortParallel(array, length);

    printf("Parallel Sorted Array:\n");
    for (int i = 0; i < length; i++) {
        printf("%d ", array[i]);
    }

    printf("\n");

    return 0;
}
```

