template<typename T>
void swap(T& a, T& b) {
    T temp = a;
    a = b;
    b = temp;
}

template<typename T>
void quadraticSort(T arr[], int size){
    for (int i = 0; i < size-1; i++) {
        for (int j = 0; j < size-i-1; j++) {
            if (arr[j+1] < arr[j]) {
                swap(arr[j], arr[j+1]);
            }
        }
    }
}

template<typename T>
void shellSort(T arr[], int size) {
    for (int gap = size/2; gap > 0; gap /= 2) {
        for (int i = gap; i < size; i++) {
            T temp = arr[i];

            int j;
            for (j = i; j >= gap && arr[j - gap] > temp; j -= gap) {
                arr[j] = arr[j - gap];
            }

            arr[j] = temp;
        }
    }
}

template<typename T>
int partition(T arr[], int low, int high) {
    T pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(arr[i], arr[j]);
        }
    }

    swap(arr[i + 1], arr[high]);
    return (i + 1);
}

template<typename T>
void quickSort(T arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);

        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

template<typename T>
int binarySearch(T arr[], int low, int high, const std::string& searchName) {
    if (high >= low) {
        int mid = low + (high - low) / 2;

        if (arr[mid].getName() == searchName) {
            return mid;
        }

        if (arr[mid].getName() > searchName) {
            return binarySearch(arr, low, mid - 1, searchName);
        }

        return binarySearch(arr, mid + 1, high, searchName);
    }

    return -1;
}

