<body>
  <div id='container' class='textarea' contenteditable='true'></div>

  <script>
    const container = document.getElementById('container');
    let previousContent = container.innerHTML;

    function insertLine() {
      const range = window.getSelection().getRangeAt(0);
      if (range.startContainer.nodeType === 3) {
        const textNode = range.startContainer;
        const currentPosition = range.startOffset;
        const lineText = textNode.textContent.slice(currentPosition);
        if (lineText.trim().length === 0) {
          return;
        }

        const highlightedLine = document.createElement('span');
        highlightedLine.textContent = lineText;

        const caretLaser = document.createElement('span');
        caretLaser.classList.add('caret-laser');

        const caretParent = document.createElement('span');
        caretParent.appendChild(caretLaser);
        caretParent.appendChild(highlightedLine);

        range.deleteContents();
        range.insertNode(caretParent);
        range.collapse();
        previousContent = container.innerHTML;

        setTimeout(() => {
          caretParent.parentNode.removeChild(caretParent);
        }, 300);
      }
    }

    function handleKeyPress(event) {
      if (event.key === 'Enter') {
        event.preventDefault();
        insertLine();
      }
    }

    function handleKeyUp(event) {
      if (event.key === 'Enter' || event.key === ' ' || event.key === ',' || event.key === '.') {
        event.preventDefault();
        if (previousContent !== container.innerHTML) {
          insertLine();
        }
      }
    }

    container.addEventListener('keydown', handleKeyPress);
    container.addEventListener('keyup', handleKeyUp);
  </script>
</body>
</html>
```

