```cpp
#include <iostream>
#include <unordered_set>
#include <vector>
using namespace std;

int main() {
    int n, m;

    // Read the size of the arrays
    cin >> n >> m;

    // Read the elements of array a
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    // Read the elements of array b
    vector<int> b(m);
    for (int i = 0; i < m; i++) {
        cin >> b[i];
    }

    // Create a set to store unique elements of array a
    unordered_set<int> uniqueElements(a.begin(), a.end());

    // Count the number of similar elements
    int count = 0;
    vector<int> similarElements;
    for (int i = 0; i < m; i++) {
        if (uniqueElements.count(b[i])) {
            count++;
            similarElements.push_back(b[i]);
        }
    }

    // Print the number of similar elements
    cout << count << endl;

    // Print the list of similar elements
    for (int i = 0; i < similarElements.size(); i++) {
        cout << similarElements[i] << " ";
    }
    cout << endl;

    return 0;
}
