void bubbleSort(std::vector<T>& arr) {
  int n = arr.size();
  for (int i = 0; i < n-1; i++) {
    for (int j = 0; j < n-i-1; j++) {
      if (arr[j] < arr[j+1]) {
        std::swap(arr[j], arr[j+1]);
      }
    }
  }
}

template<typename T>
void shellSort(std::vector<T>& arr) {
  int n = arr.size();
  for (int gap = n/2; gap > 0; gap /= 2) {
    for (int i = gap; i < n; i++) {
      T temp = arr[i];
      int j;
      for (j = i; j >= gap && arr[j - gap] < temp; j -= gap) {
        arr[j] = arr[j - gap];
      }
      arr[j] = temp;
    }
  }
}

