  int i, j, k;
  int n1 = middle - left + 1;
  int n2 =  right - middle;

  std::vector<T> L(n1), R(n2);

  for (i = 0; i < n1; i++)
    L[i] = arr[left + i];
  for (j = 0; j < n2; j++)
    R[j] = arr[middle + 1+ j];

  i = 0; j = 0; k = left;
  while (i < n1 && j < n2) {
