To calculate the total non-overlapping length covered by the sections, we need to consider only the sections that do not have any overlap with other sections.

Here's a modified version of the previous code that calculates the total non-overlapping length:

```cpp
#include<iostream>
#include<vector>
#include<algorithm>

using namespace std;

int main() {
    int n;
    cout << "Enter the number of sections: ";
    cin >> n;

    vector<int> startPoints(n);
    vector<int> endPoints(n);

    cout << "Enter the start and end points of each section:" << endl;

    for (int i = 0; i < n; i++) {
        cout << "Section " << i+1 << " start point: ";
        cin >> startPoints[i];
        cout << "Section " << i+1 << " end point: ";
        cin >> endPoints[i];
    }

    // Sort the sections based on the start points
    vector<pair<int, int>> sections;
    for (int i = 0; i < n; i++) {
        sections.push_back(make_pair(startPoints[i], endPoints[i]));
    }
    sort(sections.begin(), sections.end());

    int nonOverlappingLength = 0;
    int currentStart = sections[0].first;
    int currentEnd = sections[0].second;

    for (int i = 1; i < n; i++) {
        int nextStart = sections[i].first;
        int nextEnd = sections[i].second;

        // If there is no overlap, add the length of the section to the total non-overlapping length
        if (nextStart > currentEnd) {
            nonOverlappingLength += currentEnd - currentStart;
            // Move to the next non-overlapping section
            currentStart = nextStart;
        }

        // Update the current end point if necessary
        if (nextEnd > currentEnd) {
            currentEnd = nextEnd;
        }
    }

    // Add the length of the last non-overlapping section
    nonOverlappingLength += currentEnd - currentStart;

    cout << "Total non-overlapping length covered by the sections is: " << nonOverlappingLength << endl;

    return 0;
}
```

In this code, the sections are sorted based on their start points. Then, we iterate over the sorted sections and check for any overlap with the current non-overlapping section. If there is no overlap, we add the length of the section to the total non-overlapping length. Finally, the length of the last non-overlapping section is added to the total length.

Note: This code assumes that the start and end points are integers and that the sections are sorted in ascending order of their start points.

