        vehicleElem.style.height = vehicle.height + 'px';
        vehicleElem.style.left = vehicle.posX + 'px';
        vehicleElem.style.top = vehicle.posY + 'px';

        vehicleElem.addEventListener('mousedown', function(e) {
            if (e.button === 0) {
                var startX = e.clientX;
                var startY = e.clientY;

                var moveHandler = function(e) {
                    var deltaX = e.clientX - startX;
                    var deltaY = e.clientY - startY;
                    moveVehicle(index, deltaX, deltaY);
                    startX = e.clientX;
                    startY = e.clientY;
                };

                var upHandler = function() {
                    document.removeEventListener('mousemove', moveHandler);
                    document.removeEventListener('mouseup', upHandler);
                };

                document.addEventListener('mousemove', moveHandler);
                document.addEventListener('mouseup', upHandler);
            }
        });

        parkingLot.appendChild(vehicleElem);
    });
}
