```java
public class SimpleMethod {
    public static void main(String[] args) {
        double a = 5.2;
        double b = 4.3;
        double c = 6.1;

        double result = maxMinSumSquareRt(a, b, c);

        System.out.println("Result: " + result);
    }

    public static double maxMinSumSquareRt(double a, double b, double c) {
        double largest = Math.max(Math.max(a, b), c);
        double smallest = Math.min(Math.min(a, b), c);

        double sum = largest + smallest;
        double squareRoot = Math.sqrt(sum);

        return squareRoot;
    }
}
```

