private static Specification<Company> buildSearchValueSpecification(final String searchString) {
    if (isEmpty(searchString)) {
        return null;
    }

    return new Specification<Company>() {

        @Override
        public Predicate toPredicate(final Root<Company> root, final CriteriaQuery<?> query, final CriteriaBuilder builder) {
            try {
                // Попытка преобразовать значение в тип long
                String[] searchValues = searchString.split(",");
                long searchId = -1;
                String searchName = null;
                String searchInn = null;

                if (searchValues.length >= 3) {
                    searchId = Long.parseLong(searchValues[2]);
                }

                if (searchValues.length >= 2) {
                    searchInn = replaceMaskSymbols(searchValues[1]);
                }

                if (searchValues.length >= 1) {
                    searchName = replaceMaskSymbols(searchValues[0]);
                }

                List<Predicate> predicates = new ArrayList<>();

                if (searchId != -1) {
                    // Добавить условие поиска по полю "id"
                    predicates.add(builder.equal(root.get("id"), searchId));
                }

                if (searchName != null) {
                    // Добавить условие поиска по полю "name"
