import android.content.Context;
import android.content.res.AssetFileDescriptor;
import android.content.res.AssetManager;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.media.AudioAttributes;
import android.media.AudioManager;
import android.media.SoundPool;
import android.view.MotionEvent;
import android.view.SurfaceHolder;
import android.view.SurfaceView;

import java.io.IOException;
import java.util.Random;

public class FindDifferenceGame extends SurfaceView implements SurfaceHolder.Callback {

    private GameThread gameThread;
    private Bitmap picture1, picture2;
    private int screenWidth, screenHeight;
    private int differenceCount;
    private Difference[] differences;

    private boolean[] foundDifferences;
    private Paint circlePaint, foundCirclePaint;

    private SoundPool soundPool;
    private int soundClick, soundWin;

    private boolean isGameOver;

    public FindDifferenceGame(Context context) {
        super(context);

        // Инициализация SurfaceHolder и добавление обратного вызова
        SurfaceHolder surfaceHolder = getHolder();
        surfaceHolder.addCallback(this);

        // Инициализация потока игры
        gameThread = new GameThread(surfaceHolder);

        // Загрузка изображений
        picture1 = BitmapFactory.decodeResource(getResources(), R.drawable.picture1);
        picture2 = BitmapFactory.decodeResource(getResources(), R.drawable.picture2);

        // Получение размеров экрана
        screenWidth = getResources().getDisplayMetrics().widthPixels;
        screenHeight = getResources().getDisplayMetrics().heightPixels;

        // Масштабирование изображений под размеры экрана
        picture1 = Bitmap.createScaledBitmap(picture1, screenWidth, screenHeight, true);
        picture2 = Bitmap.createScaledBitmap(picture2, screenWidth, screenHeight, true);

        // Инициализация массива отличий
        differences = new Difference[5];
        differences[0] = new Difference(100, 100);
        differences[1] = new Difference(200, 300);
        differences[2] = new Difference(400, 200);
        differences[3] = new Difference(600, 400);
        differences[4] = new Difference(800, 100);

        // Инициализация массива для отслеживания найденных отличий
        foundDifferences = new boolean[differences.length];

        // Инициализация кистей для рисования кружков
        circlePaint = new Paint();
        circlePaint.setColor(Color.RED);
        circlePaint.setStyle(Paint.Style.STROKE);
        circlePaint.setStrokeWidth(5);

        foundCirclePaint = new Paint();
        foundCirclePaint.setColor(Color.GREEN);
        foundCirclePaint.setStyle(Paint.Style.STROKE);
        foundCirclePaint.setStrokeWidth(5);

        // Загрузка звуковых эффектов
        AudioAttributes audioAttributes = new AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build();

        soundPool = new SoundPool.Builder()
                .setMaxStreams(2)
                .setAudioAttributes(audioAttributes)
                .build();

        try {
            AssetManager assetManager = context.getAssets();
            AssetFileDescriptor descriptor;

            descriptor = assetManager.openFd("click_sound.wav");
            soundClick = soundPool.load(descriptor, 0);

            descriptor = assetManager.openFd("win_sound.wav");
            soundWin = soundPool.load(descriptor, 0);

        } catch (IOException e) {
            e.printStackTrace();
        }

        // Включение обработки нажатий
        setFocusable(true);
    }

    @Override
    public void surfaceCreated(SurfaceHolder surfaceHolder) {
        // Запуск игрового потока при создании Surface
        gameThread.setRunning(true);
        gameThread.start();
    }

    @Override
    public void surfaceChanged(SurfaceHolder surfaceHolder, int format, int width, int height) {
    }

    @Override
    public void surfaceDestroyed(SurfaceHolder surfaceHolder) {
        // Остановка игрового потока при уничтожении Surface
        boolean retry = true;
        while (retry) {
            try {
                gameThread.setRunning(false);
                gameThread.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            retry = false;
        }
    }

    @Override
    public boolean onTouchEvent(MotionEvent event) {
        if (event.getAction() == MotionEvent.ACTION_DOWN) {
            // Проверка, было ли нажатие на отличие и отметить его, если найдено
            float x = event.getX();
            float y = event.getY();

            for (int i = 0; i < differences.length; i++) {
                if (!foundDifferences[i] && differences[i].isClicked(x, y)) {
                    markDifference(i);
                }
            }
        }

        return true;
    }

    private void markDifference(int index) {
        // Воспроизведение звукового эффекта при нажатии
        soundPool.play(soundClick, 1, 1, 0, 0, 1);

        // Отметить отличие как найденное
        foundDifferences[index] = true;

        // Проверка, были ли найдены все отличия
        differenceCount++;
        if (differenceCount == differences.length) {
            isGameOver = true;
            soundPool.play(soundWin, 1, 1, 0, 0, 1);
        }
    }

    private void drawPicture(Canvas canvas, Bitmap picture) {
        canvas.drawBitmap(picture, 0, 0, null);
    }

    private void drawDifferences(Canvas canvas) {
        for (int i = 0; i < differences.length; i++) {
            if (foundDifferences[i]) {
                // Отрисовка найденных отличий
                canvas.drawCircle(differences[i].getX(), differences[i].getY(), 50, foundCirclePaint);
            } else {
                // Отрисовка оставшихся отличий
                canvas.drawCircle(differences[i].getX(), differences[i].getY(), 50, circlePaint);
            }
        }
    }

    private void drawGameOver(Canvas canvas) {
        Paint textPaint = new Paint();
        textPaint.setColor(Color.RED);
        textPaint.setStyle(Paint.Style.FILL);
        textPaint.setTextSize(100);
        textPaint.setTextAlign(Paint.Align.CENTER);

        canvas.drawText("Победа!", screenWidth / 2, (int) (screenHeight * 0.4), textPaint);
    }

    public void update() {
        // Обновление состояния игры
        if (isGameOver) {
            gameThread.setRunning(false);
        }
    }

    @Override
    public void draw(Canvas canvas) {
        super.draw(canvas);

        // Отрисовка фона и отличий
        drawPicture(canvas, picture1);
        drawDifferences(canvas);

        // При победе отрисовать сообщение о победе
        if (isGameOver) {
            drawGameOver(canvas);
        }
    }

    private class GameThread extends Thread {
        private SurfaceHolder surfaceHolder;
        private boolean isRunning;

        public GameThread(SurfaceHolder surfaceHolder) {
            this.surfaceHolder = surfaceHolder;
            isRunning = false;
        }

        public void setRunning(boolean running) {
            isRunning = running;
        }

        @Override
        public void run() {
            while (isRunning) {
                Canvas canvas = null;
                try {
                    // Получение Canvas из SurfaceHolder
                    canvas = surfaceHolder.lockCanvas();

                    // Синхронизация по поверхности
                    synchronized (surfaceHolder) {
                        // Обновление состояния игры
                        update();

                        // Отрисовка состояния игры
                        draw(canvas);
                    }
                } finally {
                    if (canvas != null) {
                        // Разблокировка Canvas
                        surfaceHolder.unlockCanvasAndPost(canvas);
                    }
                }
            }
        }
    }

    private class Difference {
        private int x, y, radius;

        public Difference(int x, int y) {
            this.x = x;
            this.y = y;
            this.radius = 50;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        public boolean isClicked(float touchX, float touchY) {
            // Проверка, было ли нажатие на отличие
            double distance = Math.sqrt(Math.pow(touchX - x, 2) + Math.pow(touchY - y, 2));

            return distance <= radius;
        }
    }
}
