#include <opencv2/opencv.hpp>

cv::Mat connect_lane(cv::Mat image, int shadow_height=0){
    cv::Mat gray_image;
    if (image.channels() == 3){
        cv::cvtColor(image, gray_image, cv::COLOR_BGR2GRAY);
    }
    else{
        gray_image = image;
    }
    if (shadow_height > 0){
        for (int i = 0; i < shadow_height; i++){
            image.row(i) = cv::Mat::zeros(1, image.cols, CV_8UC1);
        }
    }
    cv::Mat mask = cv::Mat::zeros(image.rows, image.cols, CV_8UC1);

    cv::Mat labels, stats, centers;
    int num_labels = cv::connectedComponentsWithStats(gray_image, labels, stats, centers, 8, CV_32S);

    std::vector<int> selected_label;
    for (int t = 1; t < num_labels; t++){
        int area = stats.at<int>(t, cv::CC_STAT_AREA);
        if (area > 400){
            selected_label.push_back(t);
        }
    }
    if (selected_label.empty()){
        return mask;
    }
    else{
        std::vector<std::vector<int>> split_labels;
        for (int label : selected_label){
            std::vector<int> temp;
            temp.push_back(label);
            split_labels.push_back(temp);
        }
        cv::Mat mask_post = fitlane(mask, split_labels, labels, stats);
        return mask_post;
    }
}

