        std::vector<cv::Mat> states;
        for (int k : label_group) {
            states.push_back(stats.row(k));
        }
        cv::Mat state = states[0];
        int x = state.at<int>(0);
        int y = state.at<int>(1);
        int w = state.at<int>(2);
        int h = state.at<int>(3);
        int t = label_group[0];

        std::vector<double> samples_y;
        if (w > 0){
            samples_y = std::vector<double>(30);
            double increment = static_cast<double>(h-1) / (30-1);
            for (int i = 0; i < 30; i++){
