            }
        }
        else{
            samples_y = std::vector<double>(1);
            samples_y[0] = y;
        }

        std::vector<std::vector<int>> samples_x;
        for (double sample_y : samples_y){
            std::vector<int> sample_x = cv::Mat::zeros(1, W, CV_32S).clone();
            int index = 0;
            for (int i = 0; i < W; i++){
                if (labels.at<int>(sample_y, i) == t){
