cv::Mat morphological_process(cv::Mat image, int kernel_size=5, int func_type=cv::MORPH_CLOSE) {
    if (image.channels() != 1) {
        throw std::invalid_argument("Binary segmentation result image should be a single channel image");
    }

    if (image.type() != CV_8UC1) {
        image.convertTo(image, CV_8UC1);
    }

    cv::Mat kernel = cv::getStructuringElement(cv::MORPH_ELLIPSE, cv::Size(kernel_size, kernel_size));

    cv::Mat closing;
    cv::morphologyEx(image, closing, func_type, kernel, cv::Point(-1, -1), 1);

    return closing;
}

