std::string getNextStatus(const std::vector<std::string>& statuses, int& currentStatusIndex) {
    if (statuses.empty()) {
        std::cerr << "Не заданы статусы." << std::endl;
        return "";
    }

    std::string nextStatus = statuses[currentStatusIndex];
    currentStatusIndex = (currentStatusIndex + 1) % statuses.size();
    return nextStatus;
}

