    requiresCaptcha = false;
}

void changeStatus(const std::string& token, const std::vector<std::string>& statuses, int interval) {
    static int currentStatusIndex = 0;

    std::string currentStatus = getCurrentStatus(token);

    while (requiresCaptcha) {
        std::cout << "Ожидание решения капчи..." << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(10));
        currentStatus = getCurrentStatus(token);
    }

    std::string nextStatus = getNextStatus(statuses, currentStatusIndex);

    if (nextStatus.empty()) {
        std::cerr << "Ошибка: не удалось выбрать новый статус." << std::endl;
        return;
    }

    nextStatus = urlEncode(nextStatus);

    std::string url = "https://api.vk.com/method/status.set?text=" + nextStatus + "&access_token=" + token + "&v=5.131";

    CURL* curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);

        std::string response;
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        CURLcode res = curl_easy_perform(curl);

