import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.widget.EditText;
import android.widget.ListView;
import androidx.appcompat.app.AppCompatActivity;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public class MainActivity extends AppCompatActivity {

    private ListView contactListView;
    private EditText searchEditText;
    private List<Contact> contactList;
    private ContactAdapter contactAdapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        contactListView = findViewById(R.id.contactListView);
        searchEditText = findViewById(R.id.searchEditText);

        contactList = new ArrayList<>();
        contactList.add(new Contact("John", "1234567890"));
        contactList.add(new Contact("Jane", "0987654321"));
        contactList.add(new Contact("David", "9876543210"));
        contactList.add(new Contact("Emma", "0123456789"));

        contactAdapter = new ContactAdapter(this, contactList);
        contactListView.setAdapter(contactAdapter);

        searchEditText.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) { }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                String searchText = searchEditText.getText().toString().toLowerCase(Locale.getDefault());
                contactAdapter.filter(searchText);
            }

            @Override
            public void afterTextChanged(Editable s) { }
        });
    }
}
