Create a new Java class called ContactAdapter.java to handle the ListView items.

ContactAdapter.java:
```java
import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

public class ContactAdapter extends BaseAdapter {

    private Context context;
    private List<Contact> contactList;
    private List<Contact> filteredList;

    public ContactAdapter(Context context, List<Contact> contactList) {
        this.context = context;
        this.contactList = contactList;
        this.filteredList = new ArrayList<>(contactList);
    }

    @Override
    public int getCount() {
        return filteredList.size();
    }

    @Override
    public Object getItem(int position) {
        return filteredList.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        View view = convertView;
        if (view == null) {
            LayoutInflater inflater = (LayoutInflater) context.getSystemService(Context.LAYOUT_INFLATER_SERVICE);
            view = inflater.inflate(R.layout.contact_item, null);
        }

        TextView nameTextView = view.findViewById(R.id.nameTextView);
        TextView phoneTextView = view.findViewById(R.id.phoneTextView);

        Contact contact = filteredList.get(position);
        nameTextView.setText(contact.getName());
        phoneTextView.setText(contact.getPhoneNumber());

        return view;
    }

    public void filter(String searchText) {
        searchText = searchText.toLowerCase(Locale.getDefault());
        filteredList.clear();
        if (searchText.length() == 0) {
            filteredList.addAll(contactList);
        } else {
            filteredList.addAll(contactList.stream()
                    .filter(contact -> contact.getName().toLowerCase(Locale.getDefault()).contains(searchText))
                    .collect(Collectors.toList()));
        }
        notifyDataSetChanged();
    }
}
```

