public class MainActivity extends AppCompatActivity implements SearchView.OnQueryTextListener {
    private ListView contactListView;
    private SearchView searchView;
    private ArrayAdapter<Contact> contactAdapter;
    private List<Contact> allContacts;
    private List<Contact> displayedContacts;
    private DBHelper dbHelper;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        contactListView = findViewById(R.id.contact_list_view);
        searchView = findViewById(R.id.search_view);

        dbHelper = new DBHelper(this);
        allContacts = dbHelper.getAllContacts();
        displayedContacts = new ArrayList<>(allContacts);

        contactAdapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, displayedContacts);
        contactListView.setAdapter(contactAdapter);

        searchView.setOnQueryTextListener(this);

        contactListView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> adapterView, View view, int position, long id) {
                Intent intent = new Intent(MainActivity.this, ContactDetailActivity.class);
                intent.putExtra("contact", displayedContacts.get(position));
                startActivity(intent);
            }
        });
    }

    // Implement OnQueryTextListener methods for search functionality

    @Override
    public boolean onQueryTextSubmit(String query) {
        return false;
    }

    @Override
    public boolean onQueryTextChange(String newText) {
        displayedContacts.clear();

        if (TextUtils.isEmpty(newText)) {
            displayedContacts.addAll(allContacts);
        } else {
            for (Contact contact : allContacts) {
                if (contact.getName().toLowerCase().contains(newText.toLowerCase())) {
                    displayedContacts.add(contact);
                }
            }
        }

        contactAdapter.notifyDataSetChanged();
        return true;
    }
}
