```java
import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.Filter;
import android.widget.Filterable;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.List;

public class ContactListAdapter extends BaseAdapter implements Filterable {

    private Context context;
    private List<Contact> contactList;
    private List<Contact> contactListFiltered;
    private ContactFilter contactFilter;

    public ContactListAdapter(Context context, List<Contact> contactList) {
        this.context = context;
        this.contactList = contactList;
        this.contactListFiltered = contactList;
    }

    @Override
    public int getCount() {
        return contactListFiltered.size();
    }

    @Override
    public Object getItem(int position) {
        return contactListFiltered.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        if (convertView == null) {
            LayoutInflater inflater = (LayoutInflater) context.getSystemService(Context.LAYOUT_INFLATER_SERVICE);
            convertView = inflater.inflate(R.layout.contact_list_item, null);
        }

        TextView textViewName = convertView.findViewById(R.id.textViewName);
        TextView textViewPhoneNumber = convertView.findViewById(R.id.textViewPhoneNumber);

        Contact contact = contactListFiltered.get(position);

        textViewName.setText(contact.getName());
        textViewPhoneNumber.setText(contact.getPhoneNumber());

        convertView.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Open DetailActivity to view/edit contact details
                Intent intent = new Intent(context, DetailActivity.class);
                intent.putExtra("contact", contact);
                context.startActivity(intent);
            }
        });

        return convertView;
    }

    @Override
    public Filter getFilter() {
        if (contactFilter == null) {
            contactFilter = new ContactFilter();
        }
        return contactFilter;
    }

    private class ContactFilter extends Filter {

        @Override
        protected FilterResults performFiltering(CharSequence constraint) {
            FilterResults filterResults = new FilterResults();
            List<Contact> filteredList = new ArrayList<>();

            if (constraint == null || constraint.length() == 0) {
                filteredList.addAll(contactList);
            } else {
                String filterPattern = constraint.toString().toLowerCase().trim();
                for (Contact contact : contactList) {
                    if (contact.getName().toLowerCase().contains(filterPattern)) {
                        filteredList.add(contact);
                    }
                }
            }

            filterResults.values = filteredList;
            filterResults.count = filteredList.size();
            return filterResults;
        }

        @Override
        protected void publishResults(CharSequence constraint, FilterResults results) {
            contactListFiltered = (List<Contact>) results.values;
            notifyDataSetChanged();
        }
    }
}
