import android.content.ContentValues;
import android.content.Intent;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.view.Menu;
import android.view.MenuItem;
import android.widget.EditText;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

public class DetailActivity extends AppCompatActivity {

    private EditText nameEditText;
    private EditText phoneNumberEditText;
    private DatabaseHelper databaseHelper;
    private int contactId;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_detail);

        nameEditText = findViewById(R.id.name_edit_text);
        phoneNumberEditText = findViewById(R.id.phone_number_edit_text);
        databaseHelper = new DatabaseHelper(this);

        Intent intent = getIntent();
        if (intent.hasExtra("contact_id")) {
            contactId = intent.getIntExtra("contact_id", -1);
            loadContact(contactId);
        }
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.detail_menu, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.getItemId() == R.id.save_contact) {
            saveContact();
            return true;
        } else if (item.getItemId() == R.id.delete_contact) {
            deleteContact();
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    private void loadContact(int contactId) {
        SQLiteDatabase db = databaseHelper.getReadableDatabase();

        String selection = DatabaseHelper.COL_ID + "=?";
        String[] selectionArgs = {String.valueOf(contactId)};

        Cursor cursor = db.query(DatabaseHelper.TABLE_CONTACTS,
                null,
                selection,
                selectionArgs,
                null,
                null,
                null);

        if (cursor.moveToNext()) {
            int nameIndex = cursor.getColumnIndex(DatabaseHelper.COL_NAME);
            int phoneNumberIndex = cursor.getColumnIndex(DatabaseHelper.COL_PHONE_NUMBER);

            String name = cursor.getString(nameIndex);
            String phoneNumber = cursor.getString(phoneNumberIndex);

            nameEditText.setText(name);
            phoneNumberEditText.setText(phoneNumber);
        }

        cursor.close();
        db.close();
    }

    private void saveContact() {
        String name = nameEditText.getText().toString().trim();
        String phoneNumber = phoneNumberEditText.getText().toString().trim();

        if (TextUtils.isEmpty(name) || TextUtils.isEmpty(phoneNumber)) {
            Toast.makeText(this, "Please enter name and phone number", Toast.LENGTH_SHORT).show();
            return;
        }

        SQLiteDatabase db = databaseHelper.getWritableDatabase();

        ContentValues values = new ContentValues();
        values.put(DatabaseHelper.COL_NAME, name);
        values.put(DatabaseHelper.COL_PHONE_NUMBER, phoneNumber);

        if (contactId != -1) {
            String selection = DatabaseHelper.COL_ID + "=?";
            String[] selectionArgs = {String.valueOf(contactId)};

            db.update(DatabaseHelper.TABLE_CONTACTS, values, selection, selectionArgs);
            Toast.makeText(this, "Contact updated", Toast.LENGTH_SHORT).show();
        } else {
            db.insert(DatabaseHelper.TABLE_CONTACTS, null, values);
            Toast.makeText(this, "Contact saved", Toast.LENGTH_SHORT).show();
        }

        db.close();
        finish();
    }

    private void deleteContact() {
        SQLiteDatabase db = databaseHelper.getWritableDatabase();

        String selection = DatabaseHelper.COL_ID + "=?";
        String[] selectionArgs = {String.valueOf(contactId)};

        db.delete(DatabaseHelper.TABLE_CONTACTS, selection, selectionArgs);

        Toast.makeText(this, "Contact deleted", Toast.LENGTH_SHORT).show();

        db.close();
        finish();
    }
}
