public class MainActivity extends AppCompatActivity {
    private RecyclerView recyclerView;
    private SearchView searchView;
    private ContactAdapter adapter;
    private List<Contact> contactList;
    private DatabaseHelper databaseHelper;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        recyclerView = findViewById(R.id.recyclerView);
        searchView = findViewById(R.id.searchView);
        databaseHelper = new DatabaseHelper(this);

        contactList = databaseHelper.getAllContacts();
        adapter = new ContactAdapter(contactList, new ContactAdapter.OnItemClickListener() {
            @Override
            public void onItemClick(Contact contact) {
                openDetailScreen(contact);
            }
        });

        recyclerView.setLayoutManager(new LinearLayoutManager(this));
        recyclerView.setAdapter(adapter);

        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
             @Override
             public boolean onQueryTextSubmit(String query) {
                 return false;
             }

             @Override
             public boolean onQueryTextChange(String newText) {
                 List<Contact> filteredContacts = filterContacts(newText);
                 adapter = new ContactAdapter(filteredContacts, new ContactAdapter.OnItemClickListener() {
                     @Override
                     public void onItemClick(Contact contact) {
                         openDetailScreen(contact);
                     }
                 });
                 recyclerView.setAdapter(adapter);
                 return false;
             }
        });
    }

    private List<Contact> filterContacts(String query) {
        List<Contact> filteredContacts = new ArrayList<>();
        for (Contact contact : contactList) {
            if (contact.getName().toLowerCase().contains(query.toLowerCase())) {
                filteredContacts.add(contact);
            }
        }
        return filteredContacts;
    }

    private void openDetailScreen(Contact contact) {
