```javascript
// Circle properties
const circle = {
  x: 100, // x-coordinate of the circle's center
  y: 100, // y-coordinate of the circle's center
  radius: 50, // radius of the circle
  vx: 2, // x velocity of the circle (positive means moving rightwards)
  vy: 0 // y velocity of the circle
};

// Line properties
const line = {
  x1: 200, // starting x-coordinate of the line
  y1: 50, // starting y-coordinate of the line
  x2: 200, // ending x-coordinate of the line
  y2: 150 // ending y-coordinate of the line
};

// Function to detect collision between circle and line
function detectCollision(circle, line) {
  // Get the circle's predicted future position based on its velocity
  const futureX = circle.x + circle.vx;
  const futureY = circle.y + circle.vy;

  // Check if the circle's predicted path intersects the line segment
  const intersection = lineCircleIntersection(line.x1, line.y1, line.x2, line.y2, circle.x, circle.y, futureX, futureY);

  // If there is an intersection point, check if it lies within the line segment
  if (intersection && isPointOnLine(intersection.x, intersection.y, line.x1, line.y1, line.x2, line.y2)) {
    return true;
  }

  return false;
}

// Function to calculate the intersection point between a line segment and a circle's predicted path
function lineCircleIntersection(x1, y1, x2, y2, cx, cy, futureX, futureY) {
  // Convert line segment to vector
  const lineVectorX = x2 - x1;
  const lineVectorY = y2 - y1;

  // Convert circle's predicted path to vector
  const circleVectorX = futureX - cx;
  const circleVectorY = futureY - cy;

  // Calculate unit vector of line segment
  const lineLength = Math.sqrt(lineVectorX ** 2 + lineVectorY ** 2);
  const lineUnitVectorX = lineVectorX / lineLength;
  const lineUnitVectorY = lineVectorY / lineLength;

  // Calculate vector projection of circle's predicted path onto line segment
  const projection = circleVectorX * lineUnitVectorX + circleVectorY * lineUnitVectorY;

  // Calculate closest point on line segment
  const closestX = x1 + projection * lineUnitVectorX;
  const closestY = y1 + projection * lineUnitVectorY;

  // Check if the closest point is within the line segment
  if (isPointOnLine(closestX, closestY, x1, y1, x2, y2)) {
    return { x: closestX, y: closestY };
  }

  return null;
}

// Function to check if a point lies within a line segment
function isPointOnLine(px, py, x1, y1, x2, y2) {
  const d1 = distance(px, py, x1, y1);
  const d2 = distance(px, py, x2, y2);
  const lineLength = distance(x1, y1, x2, y2);
  const buffer = 0.1; // Buffer to account for floating-point calculation errors

  return d1 + d2 >= lineLength - buffer && d1 + d2 <= lineLength + buffer;
}

// Function to calculate distance between two points
function distance(x1, y1, x2, y2) {
  return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

// Example usage
function update() {
  // Save the current position to use in collision detection
  const prevX = circle.x;
  const prevY = circle.y;

  // Update circle position based on its velocity
  circle.x += circle.vx;
  circle.y += circle.vy;

  // Detect collision with the line
  const collision = detectCollision(circle, line);

  if (collision) {
    // Handle collision
    console.log("Collision detected!");

    // Stop the circle from moving further
    circle.x = prevX;
    circle.y = prevY;
    circle.vx = 0;
    circle.vy = 0;
  }

  // Continue updating the circle's position or perform other actions
}

// Call update function repeatedly (e.g., using setInterval or requestAnimationFrame)
setInterval(update, 16); // Assuming 60 FPS
