  if (intersection && isPointOnLine(intersection.x, intersection.y, line.x1, line.y1, line.x2, line.y2)) {
    // Calculate the Time of Impact (TOI)
    const distance = Math.sqrt((circle.x - intersection.x) ** 2 + (circle.y - intersection.y) ** 2);
    const futureDistance = Math.sqrt((futureX - intersection.x) ** 2 + (futureY - intersection.y) ** 2);
    const toi = distance / (distance + futureDistance);

    return {
      collided: true,
      toi: toi,
      collision_point: intersection
    };
  }

  return {
    collided: false,
    toi: null,
    collision_point: null
  };
}

// Function to calculate the intersection point between a line segment and a circle's predicted path
function lineCircleIntersection(x1, y1, x2, y2, cx, cy, futureX, futureY) {
  const lineVectorX = x2 - x1;
  const lineVectorY = y2 - y1;
  const circleVectorX = futureX - cx;
  const circleVectorY = futureY - cy;

  const lineLength = Math.sqrt(lineVectorX ** 2 + lineVectorY ** 2);
  const lineUnitVectorX = lineVectorX / lineLength;
  const lineUnitVectorY = lineVectorY / lineLength;

  const projection = circleVectorX * lineUnitVectorX + circleVectorY * lineUnitVectorY;

  const closestX = x1 + projection * lineUnitVectorX;
  const closestY = y1 + projection * lineUnitVectorY;

  if (isPointOnLine(closestX, closestY, x1, y1, x2, y2)) {
    return { x: closestX, y: closestY };
  }

  return null;
}

// Function to check if a point lies within a line segment
function isPointOnLine(px, py, x1, y1, x2, y2) {
  const d1 = distance(px, py, x1, y1);
  const d2 = distance(px, py, x2, y2);
  const lineLength = distance(x1, y1, x2, y2);
  const buffer = 0.1; // Buffer to account for floating-point calculation errors

  return d1 + d2 >= lineLength - buffer && d1 + d2 <= lineLength + buffer;
}

// Function to calculate distance between two points
function distance(x1, y1, x2, y2) {
  return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

