// Node is custom type that represents *model.ENodeB and *model.EUtranCellData
// of cosite Node for Elastic Ran
type Node struct {
	ENodeB         `json:"ENodeB"`
	EUtranCellData `json:"EUtranCellData"`
}

// Nodes is custom type that represents map of *model.Node
type Nodes map[string]*Node

// ValidateEach validates each node in Nodes
func (nodes Nodes) ValidateEach() error {
	return validation.Validate(
		nodes,
		validation.Required.Error("Cosite nodes cannot be blank"),
	)
}

// CleanEmpty deletes Cosite node if lte cell datya is empty
func (nodes *Nodes) CleanEmpty() {
	for name, node := range *nodes {
		if len(node.EUtranCellData.CellsGroups) == 0 {
			delete(*nodes, name)
		}
	}
}

// Count counts number of Cosite nodes
func (nodes *Nodes) Count() int {
	count := 0
	for _, node := range *nodes {
		if len(node.EUtranCellData.CellsGroups) > 0 {
			count++
		}
	}
	return count
}

// Count counts number of Cosite nodes
func (nodes *Nodes) Names() []string {
	names := make([]string, len(*nodes))
	i := 0
	for node := range *nodes {
		names[i] = node
		i++
	}
	return names
}

