int BevObstacleDetectionComponent::WriteResultImageMessage(std::map<uint64_t, BevCameraFrame> &CameraFrameSet){

  for (const auto &timestamp_cameraframe : CameraFrameSet){
    const auto &frame = timestamp_cameraframe.second;
    const std::string &camera_name = frame.camera_name;

    apollo::drivers::Image image_message;
    if (frame.camera_result_image == nullptr) continue;
    const auto &mat_image = *frame.camera_result_image;
    double publish_time = Clock::NowInSeconds();
    apollo::common::Header *header = image_message.mutable_header();
    header->set_timestamp_sec(publish_time);

    image_message.set_width(mat_image.cols);
    image_message.set_height(mat_image.rows);
    image_message.set_step(3 * mat_image.cols);
    image_message.set_data(mat_image.data, mat_image.size[0] * mat_image.size[1] *
                                        mat_image.channels());

    camera_image_output_writer_[camera_name]->Write(image_message);
  }  

  return cyber::SUCC;
}
