import java.util.Arrays;
import java.util.Scanner;

public class ReverseArray {
    public static void main(String[] args) {
        // Create a Scanner object to read the user input
        Scanner scanner = new Scanner(System.in);

        // Ask the user how many numbers should be read
        System.out.print("Enter the length of the array: ");
        int length = scanner.nextInt();

        // Create an array to store the numbers
        int[] numbers = new int[length];

        // Ask the user to enter each number
        for (int i = 0; i < length; i++) {
            System.out.print("Enter number " + (i+1) + ": ");
            numbers[i] = scanner.nextInt();
        }

        // Print the entered array using Arrays.toString()
        System.out.println("Entered array: " + Arrays.toString(numbers));

        // Reverse the array
        int[] reversedNumbers = new int[length];
        for (int i = 0; i < length; i++) {
            reversedNumbers[i] = numbers[length-1-i];
        }

        // Print the reversed array using Arrays.toString()
        System.out.println("Reversed array: " + Arrays.toString(reversedNumbers));

        // Close the Scanner object
        scanner.close();
    }
}
```

