import java.util.List;

public class MainActivity extends AppCompatActivity {

    private ListView contactListView;
    private ContactListAdapter contactListAdapter;
    private List<Contact> contacts;
    private SearchView searchView;
    private Button addContactButton;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        contacts = new ArrayList<>();
        contactListView = findViewById(R.id.contact_list);
        searchView = findViewById(R.id.search_view);
        addContactButton = findViewById(R.id.add_contact_button);

        // Set up the adapter for the contact list
        contactListAdapter = new ContactListAdapter(this, contacts);
        contactListView.setAdapter(contactListAdapter);

        // Set up click listener for each contact item
        contactListView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                Contact selectedContact = contacts.get(position);
                Intent intent = new Intent(MainActivity.this, EditContactActivity.class);
                intent.putExtra("contact", selectedContact);
                startActivity(intent);
            }
        });

        // Set up click listener for add contact button
        addContactButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, EditContactActivity.class);
                startActivity(intent);
            }
        });

        // Set up search functionality
        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                return false;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                contactListAdapter.getFilter().filter(newText);
                return false;
            }
        });
    }

    @Override
    protected void onResume() {
        super.onResume();
        // Refresh the contact list when the activity resumes
        contactListAdapter.notifyDataSetChanged();
    }
}
