import android.app.AlertDialog;
import android.content.DialogInterface;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;

import androidx.appcompat.app.AppCompatActivity;

public class EditContactActivity extends AppCompatActivity {

    private EditText nameEditText;
    private EditText phoneEditText;
    private Button saveButton;
    private Button deleteButton;
    private Contact contact;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_edit);

        nameEditText = findViewById(R.id.name_edit_text);
        phoneEditText = findViewById(R.id.phone_edit_text);
        saveButton = findViewById(R.id.save_button);
        deleteButton = findViewById(R.id.delete_button);

        // Check if an existing contact is passed from MainActivity
        contact = (Contact) getIntent().getSerializableExtra("contact");

        if (contact != null) {
            nameEditText.setText(contact.getName());
            phoneEditText.setText(contact.getPhoneNumber());

            // Set up click listener for delete button
            deleteButton.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    new AlertDialog.Builder(EditContactActivity.this)
                            .setTitle("Delete Contact")
                            .setMessage("Are you sure you want to delete this contact?")
                            .setPositiveButton(android.R.string.yes, new DialogInterface.OnClickListener() {
                                public void onClick(DialogInterface dialog, int which) {
                                    // Delete the contact
                                    ContactsDatabase.getInstance(EditContactActivity.this).contactDao().delete(contact);
                                    finish();
                                }
                            })
                            .setNegativeButton(android.R.string.no, null)
                            .show();
                }
            });
        } else {
            // Hide the delete button for new contact
            deleteButton.setVisibility(View.GONE);
        }

        // Set up click listener for save button
        saveButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String name = nameEditText.getText().toString();
                String phoneNumber = phoneEditText.getText().toString();

                if (contact == null) {
                    // Create a new contact
                    contact = new Contact(name, phoneNumber);
                    ContactsDatabase.getInstance(EditContactActivity.this).contactDao().insert(contact);
                } else {
                    // Update the existing contact
                    contact.setName(name);
                    contact.setPhoneNumber(phoneNumber);
