import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

public class SecondScreenActivity extends AppCompatActivity {

    private Contact contact;
    private EditText editTextName;
    private EditText editTextPhoneNumber;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_second_screen);

        Intent intent = getIntent();
        contact = (Contact) intent.getSerializableExtra("contact");

        editTextName = findViewById(R.id.editTextName);
        editTextPhoneNumber = findViewById(R.id.editTextPhoneNumber);

        editTextName.setText(contact.getName());
        editTextPhoneNumber.setText(contact.getPhoneNumber());

        Button buttonSave = findViewById(R.id.buttonSave);
        Button buttonDelete = findViewById(R.id.buttonDelete);

        buttonSave.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String newName = editTextName.getText().toString().trim();
                String newPhoneNumber = editTextPhoneNumber.getText().toString().trim();

                if (TextUtils.isEmpty(newName) || TextUtils.isEmpty(newPhoneNumber)) {
                    Toast.makeText(SecondScreenActivity.this, "Please enter a name and phone number", Toast.LENGTH_SHORT).show();
                } else {
                    contact = new Contact(newName, newPhoneNumber);
                    Toast.makeText(SecondScreenActivity.this, "Contact saved", Toast.LENGTH_SHORT).show();
                }
            }
        });

        buttonDelete.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                contact = null;
                Toast.makeText(SecondScreenActivity.this, "Contact deleted", Toast.LENGTH_SHORT).show();
                finish();
            }
        });
    }

    @Override
    protected void onPause() {
        super.onPause();

        // Save the updated or deleted contact here
        // You can save it to a database or use SharedPreferences
    }
}
