import java.util.Map;

public class FirstScreen extends AppCompatActivity {

    private ListView listView;
    private ContactListAdapter adapter;
    private ArrayList<Contact> contactList;
    private SharedPreferences sharedPreferences;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_first_screen);

        listView = findViewById(R.id.listView);
        Button addButton = findViewById(R.id.addButton);

        contactList = new ArrayList<>();
        sharedPreferences = PreferenceManager.getDefaultSharedPreferences(this);

        addButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                Intent intent = new Intent(FirstScreen.this, SecondScreen.class);
                startActivity(intent);
            }
        });

        // Set up search functionality
        SearchView searchView = findViewById(R.id.searchView);
        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                return false;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                adapter.getFilter().filter(newText);
                return false;
            }
        });

        // Get the contacts from sharedpreferences
        Map<String, ?> contactsMap = sharedPreferences.getAll();
        for (Map.Entry<String, ?> entry : contactsMap.entrySet()) {
            String contactName = entry.getKey();
            String phoneNumber = (String) entry.getValue();
            contactList.add(new Contact(contactName, phoneNumber));
        }

        adapter = new ContactListAdapter(this, R.layout.contact_list_item, contactList);
