        for (Map.Entry<String, ?> entry : contactsMap.entrySet()) {
            String contactName = entry.getKey();
            String phoneNumber = (String) entry.getValue();
            contactList.add(new Contact(contactName, phoneNumber));
        }

        adapter.notifyDataSetChanged();
    }
