import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Spinner;

public class SecondScreen extends AppCompatActivity {

    private EditText nameEditText;
    private EditText phoneEditText;
    private Spinner groupSpinner;
    private String originalContactName;
    private SharedPreferences sharedPreferences;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_second_screen);

        nameEditText = findViewById(R.id.nameEditText);
        phoneEditText = findViewById(R.id.phoneEditText);
        groupSpinner = findViewById(R.id.groupSpinner);
        Button saveButton = findViewById(R.id.saveButton);
        Button deleteButton = findViewById(R.id.deleteButton);

        sharedPreferences = PreferenceManager.getDefaultSharedPreferences(this);

        Bundle extras = getIntent().getExtras();
        if (extras != null) {
            String contactName = extras.getString("contactName");
            String phoneNumber = extras.getString("phoneNumber");
            originalContactName = contactName;

            nameEditText.setText(contactName);
            phoneEditText.setText(phoneNumber);
        }

        // Populate spinner with groups
        ArrayAdapter<CharSequence> adapter = ArrayAdapter.createFromResource(this,
                R.array.groups_array, android.R.layout.simple_spinner_item);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        groupSpinner.setAdapter(adapter);

        saveButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                String contactName = nameEditText.getText().toString();
                String phoneNumber = phoneEditText.getText().toString();
                String group = groupSpinner.getSelectedItem().toString();

                // Remove original contact if name is modified
                if (originalContactName != null && !originalContactName.equals(contactName)) {
                    sharedPreferences.edit().remove(originalContactName).apply();
                }

                // Save contact using sharedpreferences
                sharedPreferences.edit().putString(contactName, phoneNumber).apply();
                sharedPreferences.edit().putString(contactName + "_group", group).apply();
                finish();
            }
        });

        deleteButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                String contactName = nameEditText.getText().toString();

                // Remove contact using sharedpreferences
                sharedPreferences.edit().remove(contactName).apply();
                sharedPreferences.edit().remove(contactName + "_group").apply();
                finish();
            }
        });
    }
}
```

