import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ArrayAdapter;
import android.widget.Filter;
import android.widget.TextView;

import java.util.ArrayList;
import java.util.List;

public class ContactListAdapter extends ArrayAdapter<Contact> {

    private Context context;
    private int resource;
    private List<Contact> contactList;
    private List<Contact> filteredContactList;

    public ContactListAdapter(Context context, int resource, List<Contact> contactList) {
        super(context, resource, contactList);
        this.context = context;
        this.resource = resource;
        this.contactList = contactList;
        this.filteredContactList = contactList;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        if (convertView == null) {
            LayoutInflater layoutInflater = LayoutInflater.from(context);
            convertView = layoutInflater.inflate(resource, null);
        }

        TextView nameTextView = convertView.findViewById(R.id.nameTextView);
        TextView phoneTextView = convertView.findViewById(R.id.phoneTextView);
        TextView groupTextView = convertView.findViewById(R.id.groupTextView);

        Contact contact = filteredContactList.get(position);
        nameTextView.setText(contact.getName());
        phoneTextView.setText(contact.getPhoneNumber());
        groupTextView.setText(contact.getGroup());

        return convertView;
    }

    @Override
    public int getCount() {
        return filteredContactList.size();
    }

    @Override
    public Filter getFilter() {
        Filter filter = new Filter() {
            @Override
            protected FilterResults performFiltering(CharSequence constraint) {
                FilterResults filterResults = new FilterResults();

                if (constraint == null || constraint.length() == 0) {
                    filterResults.count = contactList.size();
                    filterResults.values = contactList;
                } else {
                    String filterPattern = constraint.toString().toLowerCase().trim();
                    List<Contact> filteredList = new ArrayList<>();

                    for (Contact contact : contactList) {
                        if (contact.getName().toLowerCase().contains(filterPattern)) {
                            filteredList.add(contact);
                        }
                    }

                    filterResults.count = filteredList.size();
                    filterResults.values = filteredList;
                }

                return filterResults;
            }

            @Override
            protected void publishResults(CharSequence constraint, FilterResults results) {
                filteredContactList = (List<Contact>) results.values;
                notifyDataSetChanged();
            }
        };

        return filter;
    }
}
```

In this updated version of the `ContactListAdapter`, the `getView()` method has been modified to populate the `groupTextView` with the group information for each contact.

