کد درست شده به شکل زیر است:

```cpp
#include <iostream>
#include <cstdlib>
#include <ctime>
#include <omp.h>

void multiply_matrices(int n) {
    int **matrix1 = new int*[n];
    int **matrix2 = new int*[n];
    int **result = new int*[n];

    srand(time(0));
    for (int i = 0; i < n; i++) {
        matrix1[i] = new int[n];
        matrix2[i] = new int[n];
        result[i] = new int[n];

        for (int j = 0; j < n; j++) {
            matrix1[i][j] = rand() % 10;
            matrix2[i][j] = rand() % 10;
        }
    }

    #pragma omp parallel for collapse(2)
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result[i][j] = 0;
            for (int k = 0; k < n; k++) {
                result[i][j] += matrix1[i][k] * matrix2[k][j];
            }
        }
    }

    std::cout << "result:" << std::endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cout << result[i][j] << " ";
        }
        std::cout << std::endl;
    }

    for (int i = 0; i < n; i++) {
        delete[] matrix1[i];
        delete[] matrix2[i];
        delete[] result[i];
    }
    delete[] matrix1;
    delete[] matrix2;
    delete[] result;
}

int main() {
    int n;
    std::cout << "enter n:";
    std::cin >> n;

    multiply_matrices(n);

    return 0;
}
```

