Из-за ограничения использования памяти в 500 МБ, нам нужно придумать другой способ реализации паттерна Memento для вектора. 

Один из подходов - хранить только разницу между текущим состоянием вектора и предыдущим состоянием, а не полное состояние. Таким образом, мы сможем сэкономить память и выполнить условия задачи.

Основные изменения в реализации будут в классе `Memento`. Вместо хранения всего состояния вектора, мы будем хранить только разницу (`delta`) между предыдущим и текущим состоянием.

```cpp
#include <iostream>
#include <vector>
#include <memory>

class Memento {
private:
    std::vector<int> delta;
    int index;

public:
    Memento(const std::vector<int>& prevState, const std::vector<int>& currentState) {
        int size = currentState.size();
        int prevSize = prevState.size();

        // Находим разницу между предыдущим и текущим состоянием
        if (size > prevSize) {
            index = prevSize;
            for (int i = prevSize; i < size; ++i) {
                delta.push_back(currentState[i]);
            }
        } else {
            // Если новое состояние меньше предыдущего
            index = size;
            for (int i = size; i < prevSize; ++i) {
                delta.push_back(prevState[i]);
            }
        }
    }

    std::vector<int> getDelta() const {
        return delta;
    }

    int getIndex() const {
        return index;
    }
};

class CustomVector {
private:
    std::vector<int> vec;
    std::vector<std::unique_ptr<Memento>> mementos;

public:
    CustomVector() {}

    void PushBack(int value) {
        vec.push_back(value);
    }

    void PopBack() {
        vec.pop_back();
    }

    void Set(int index, int value) {
        if (index >= 0 && index < vec.size()) {
            vec[index] = value;
        }
    }

    int Get(int index) const {
        if (index >= 0 && index < vec.size()) {
            return vec[index];
        }
        return -1;
    }

    Memento CreateMemento() {
        std::vector<int> prevState;
        if (mementos.empty()) {
            prevState = std::vector<int>();
        } else {
            prevState = vec;
        }

        std::vector<int> currentState = vec;

        // Создаем и сохраняем новый снимок
        std::unique_ptr<Memento> memento = std::make_unique<Memento>(prevState, currentState);
        mementos.push_back(std::move(memento));

        return *mementos.back();
    }

    void Restore(const Memento& memento) {
        int index = memento.getIndex();
        std::vector<int> delta = memento.getDelta();

        // Восстанавливаем предыдущее состояние вектора
        vec.resize(index);
        for (int i = 0; i < delta.size(); ++i) {
            vec.push_back(delta[i]);
        }
    }
};
```

В этой реализации мы храним только изменения (`delta`) между предыдущим и текущим состоянием вектора. При сохранении снимка (`CreateMemento`), мы находим разницу между текущим и предыдущим состояниями. При восстановлении (`Restore`), мы используем `delta` и `index` из снимка, чтобы вернуться к предыдущему состоянию вектора.

Эта реализация позволяет сэкономить память, сохраняя только необходимые изменения.

