You can use the `SendInput` function from the `user32.dll` library to send mouse input to a background window in C#. Here's an example of sending a right mouse click to the background window:

```csharp
using System;
using System.Runtime.InteropServices;

public class Program
{
    [DllImport("user32.dll", SetLastError = true)]
    static extern uint SendInput(uint nInputs, INPUT[] pInputs, int cbSize);

    [DllImport("user32.dll", SetLastError = true)]
    static extern IntPtr FindWindow(string lpClassName, string lpWindowName);

    [DllImport("user32.dll", SetLastError = true)]
    static extern IntPtr SetForegroundWindow(IntPtr hWnd);

    [DllImport("user32.dll", SetLastError = true)]
    static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

    [DllImport("user32.dll", SetLastError = true)]
    static extern bool ClientToScreen(IntPtr hWnd, ref POINT lpPoint);

    [StructLayout(LayoutKind.Sequential)]
    struct INPUT
    {
        public uint type;
        public MOUSEINPUT mi;
    }

    [StructLayout(LayoutKind.Sequential)]
    struct MOUSEINPUT
    {
        public int dx;
        public int dy;
        public uint mouseData;
        public uint dwFlags;
        public uint time;
        public IntPtr dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    struct POINT
    {
        public int X;
        public int Y;
    }

    [StructLayout(LayoutKind.Sequential)]
    struct RECT
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    const int INPUT_MOUSE = 0;
    const uint MOUSEEVENTF_RIGHTDOWN = 0x0008;
    const uint MOUSEEVENTF_RIGHTUP = 0x0010;

    public static void Main()
    {
        // Find the window by class name or window name
        IntPtr hWnd = FindWindow(null, "Window Title");
        if (hWnd == IntPtr.Zero)
        {
            Console.WriteLine("Window not found.");
            return;
        }

        // Bring the window to the foreground
        SetForegroundWindow(hWnd);

        // Get the window's position and size
        RECT windowRect;
        GetWindowRect(hWnd, out windowRect);

        // Calculate the click position relative to the window
        POINT clickPos;
        clickPos.X = (windowRect.Right - windowRect.Left) / 2;
        clickPos.Y = (windowRect.Bottom - windowRect.Top) / 2;

        // Convert the click position to screen coordinates
        ClientToScreen(hWnd, ref clickPos);

        // Simulate the right mouse button down and up events at the click position
        INPUT[] inputs = new INPUT[2];
        inputs[0] = CreateMouseDownInput(clickPos.X, clickPos.Y);
        inputs[1] = CreateMouseUpInput(clickPos.X, clickPos.Y);

        SendInput((uint)inputs.Length, inputs, Marshal.SizeOf(typeof(INPUT)));

        Console.WriteLine("Right click sent.");
    }

    static INPUT CreateMouseDownInput(int x, int y)
    {
        var input = new INPUT();
        input.type = INPUT_MOUSE;
        input.mi.dx = x;
        input.mi.dy = y;
        input.mi.dwFlags = MOUSEEVENTF_RIGHTDOWN;
        return input;
    }

    static INPUT CreateMouseUpInput(int x, int y)
    {
        var input = new INPUT();
        input.type = INPUT_MOUSE;
        input.mi.dx = x;
        input.mi.dy = y;
        input.mi.dwFlags = MOUSEEVENTF_RIGHTUP;
        return input;
    }
}
```

Replace `"Window Title"` with the title of the background window you want to send the right mouse click to. This code finds the window, brings it to the foreground, calculates the click position relative to the window, converts it to screen coordinates, and then sends the right mouse button down and up events to that position using `SendInput`.

