typedef struct {
    int u;
    int v;
    int weight;
} Edge;

typedef struct {
    int n;
    int e;
    int edges[MAXV][MAXV];
} MGraph;

int cmp(const void *a, const void *b) {
    return ((Edge *)a)->weight - ((Edge *)b)->weight;
}

void Kruskal(MGraph g) {
    int i, j, k;
    int edge_count = 0;
    int *visited = (int *)malloc(g.n * sizeof(int));
    for (i = 0; i < g.n; i++) {
        visited[i] = 0;
    }

    Edge *edges = (Edge *)malloc((g.n * (g.n - 1) / 2) * sizeof(Edge));
    k = 0;
    for (i = 0; i < g.n; i++) {
        for (j = i + 1; j < g.n; j++) {
            if (g.edges[i][j] != 32767) {
                edges[k].u = i;
                edges[k].v = j;
                edges[k].weight = g.edges[i][j];
                k++;
            }
        }
    }
    qsort(edges, g.n * (g.n - 1) / 2, sizeof(Edge), cmp);

    printf("Krusal:\n");
    while (edge_count < g.n - 1) {
        int min = 32767;
        int u, v;
        for (i = 0; i < g.n * (g.n - 1) / 2; i++) {
            if (!visited[edges[i].u] || !visited[edges[i].v]) {
                if (edges[i].weight < min) {
                    min = edges[i].weight;
                    u = edges[i].u;
                    v = edges[i].v;
                }
            }
        }
        printf("(%d,%d):%d\n", u, v, min);
        visited[u] = 1;
        visited[v] = 1;
        edge_count++;
    }

    free(visited);
    free(edges);
}

void Prim(MGraph g, int start) {
    int i, j, k;
    int *visited = (int *)malloc(g.n * sizeof(int));
    for (i = 0; i < g.n; i++) {
        visited[i] = 0;
    }

    printf("Prim:\n");
    visited[start] = 1;
    int edge_count = 0;
    while (edge_count < g.n - 1) {
        int min = 32767;
        int u = -1, v = -1;
        for (i = 0; i < g.n; i++) {
            if (visited[i]) {
                for (j = 0; j < g.n; j++) {
                    if (!visited[j] && g.edges[i][j] < min) {
                        min = g.edges[i][j];
                        u = i;
                        v = j;
                    }
                }
            }
        }
        visited[v] = 1;
        printf("(%d,%d):%d\n", u, v, min);
        edge_count++;
    }

    free(visited);
}

int main() {
