#include <stdio.h>
#include <stdlib.h>

#define MAXV 100
#define INF 32767

typedef struct {
    int u, v;
    int weight;
} Edge;

typedef struct {
    int n, e;
    int edges[MAXV][MAXV];
} MGraph;

int parent[MAXV];

void MakeSet(int n) {
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }
}

int Find(int x) {
    while (x != parent[x]) {
        x = parent[x];
    }
    return x;
}

int Union(int x, int y) {
    int rootx = Find(x);
    int rooty = Find(y);
    if (rootx != rooty) {
        parent[rootx] = rooty;
        return 1;
    }
    return 0;
}

int Compare(const void* a, const void* b) {
    return ((Edge*)a)->weight - ((Edge*)b)->weight;
}

void Kruskal(MGraph g) {
    Edge edges[MAXV * MAXV];
    int count = 0;
    for (int i = 0; i < g.n; i++) {
        for (int j = i + 1; j < g.n; j++) {
            if (g.edges[i][j] != INF) {
                edges[count].u = i;
                edges[count].v = j;
                edges[count].weight = g.edges[i][j];
                count++;
            }
        }
    }
    qsort(edges, count, sizeof(Edge), Compare);

    MakeSet(g.n);
    printf("krusal:\n");
    for (int i = 0; i < count; i++) {
        if (Union(edges[i].u, edges[i].v)) {
            printf("(%d,%d):%d\n", edges[i].u, edges[i].v, edges[i].weight);
        }
    }
}

void Prim(MGraph g, int start) {
    int lowcost[MAXV];
    int closest[MAXV];
    int visited[MAXV];

    for (int i = 0; i < g.n; i++) {
        lowcost[i] = g.edges[start][i];
        closest[i] = start;
        visited[i] = 0;
    }
    visited[start] = 1;

    printf("prim:\n");
    for (int i = 1; i < g.n; i++) {
        int min = INF, min_node = -1;
        for (int j = 0; j < g.n; j++) {
            if (!visited[j] && lowcost[j] < min) {
                min = lowcost[j];
                min_node = j;
            }
        }
        if (min_node != -1) {
            printf("(%d,%d):%d\n", closest[min_node], min_node, min);
            visited[min_node] = 1;
            for (int j = 0; j < g.n; j++) {
