```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <sstream>

using namespace std;

int main() {
    ifstream infile("matrix.txt");
    ofstream outfile("matrix_rowsum.txt");

    if (!infile) {
        cerr << "Error opening input file." << endl;
        return 1;
    }

    if (!outfile) {
        cerr << "Error opening output file." << endl;
        return 1;
    }

    int m, n;
    if (!(infile >> m >> n)) {
        cerr << "Invalid file format. Failed to read matrix dimensions." << endl;
        return 1;
    }

    if (m <= 0 || n <= 0) {
        cerr << "Invalid matrix dimensions. Dimensions must be positive." << endl;
        return 1;
    }

    vector<vector<int>> matrix;

    for (int i = 0; i < m; i++) {
        vector<int> row;
        string line;
        if (!getline(infile, line)) {
            cerr << "Invalid file format. Failed to read matrix element." << endl;
            return 1;
        }
        stringstream ss(line);
        int num;
        while (ss >> num) {
            row.push_back(num);
        }
        if (row.size() != n) {
            cerr << "Invalid matrix. Row size does not match the specified column count." << endl;
            return 1;
        }
        matrix.push_back(row);
    }

    for (int i = 0; i < m; i++) {
        int rowSum = 0;
        for (int j = 0; j < n; j++) {
            rowSum += matrix[i][j];
        }
        outfile << rowSum << endl;
    }

    infile.close();
    outfile.close();

    return 0;
}
