#include <iostream>
#include <cstring>

using namespace std;

const int MAX_LEN = 256;

bool is_lowercase_alphabet(char c) {
   return (c >= 'a' && c <= 'z');
}

bool correct_word(char word[], int start, int end) {
   // Base case: single lowercase alphabet character is a correct word
   if (start == end && is_lowercase_alphabet(word[start])) {
      return true;
   }
   // Recursive cases
   else if (end - start >= 1) {
      // Rule 2: s@ is a correct word if s is a correct word
      if (word[end] == '@' && correct_word(word, start, end - 1)) {
         return true;
      }
      // Rule 3: s# is a correct word if s is a correct word
      else if (word[end] == '#' && correct_word(word, start, end - 1)) {
         return true;
      }
      // Rule 4: st| is a correct word if both s and t are correct words
      else if (word[end] == '|' && correct_word(word, start, end - 1)) {
         for(int i = start; i < end; i++) {
            if (correct_word(word, start, i) && correct_word(word, i + 1, end - 1)) {
               return true;
            }
         }
      }
      // Rule 5: #st is a correct word if both s and t are correct words
      else if (word[start] == '#' && correct_word(word, start + 1, end)) {
         for(int i = start + 1; i <= end; i++) {
            if (correct_word(word, start + 1, i) && correct_word(word, i + 1, end)) {
               return true;
            }
         }
      }
   }
   // Rule 1: single lowercase alphabet character is a correct word
   else if (start == end && is_lowercase_alphabet(word[start])) {
      return true;
   }
   // If none of the rules match, the word is incorrect
   return false;
}

