        // Flip Mario’s sprite based on his movement direction
        if (movement > 0)
        {
            transform.localScale = new Vector3(1f, 1f, 1f); // Facing right
        }
        else if (movement < 0)
        {
            transform.localScale = new Vector3(-1f, 1f, 1f); // Facing left
        }

        // Make Mario jump
        if (Input.GetButtonDown("Jump") && !isJumping)
        {
            rb2d.AddForce(new Vector2(0f, jumpForce), ForceMode2D.Impulse);
            isJumping = true;
        }

        // Check for ladder climbing
        if (Input.GetButtonDown("Vertical") && !isJumping)
        {
            RaycastHit2D hit = Physics2D.Raycast(transform.position, Vector2.up, 1f, ladderLayer);
            if (hit.collider != null)
            {
                isClimbing = true;
                rb2d.gravityScale = 0f;
            }
        }

        // Climb ladder
        if (isClimbing)
        {
            float climbMovement = Input.GetAxis("Vertical");
            rb2d.velocity = new Vector2(rb2d.velocity.x, climbMovement * climbSpeed);

            // Check if Mario is no longer climbing ladder
            if (Input.GetButtonDown("Jump") || !isClimbing)
            {
                isClimbing = false;
                rb2d.gravityScale = 1f;
            }
        }
    }

    private void OnCollisionEnter2D(Collision2D collision)
    {
        // Reset jumping when Mario touches the ground
        if (collision.gameObject.CompareTag("Ground"))
        {
            isJumping = false;
        }
    }
}
