  let values = [];

  for (let key in obj) {
    if (obj.hasOwnProperty(key)) {
      let typeObj = obj[key];

      for(let typeKey in typeObj) {
        if (typeObj.hasOwnProperty(typeKey) && (typeKey === 'Read' || typeKey === 'Write')) {
