Here's a C++ program that initializes a dynamic array with random integers, prints it, calculates the min element and brings it to the beginning of the array, and sorts the array using bubble sort:

```cpp
#include <iostream>
#include <cstdlib>
#include <ctime>

void initializeArray(int* arr, int size) {
    srand(static_cast<unsigned>(time(nullptr)));
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 21 - 10; // Generate random integers from -10 to 10
    }
}

void printArray(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;
}

void bringMinElementToFront(int* arr, int size) {
    int minIndex = 0;
    for (int i = 1; i < size; i++) {
        if (arr[i] < arr[minIndex]) {
            minIndex = i;
        }
    }
    std::swap(arr[minIndex], arr[0]);
}

void bubbleSort(int* arr, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    int size;
    std::cout << "Enter the size of the array: ";
    std::cin >> size;

    int* arr = new int[size];
    initializeArray(arr, size);

    std::cout << "Array before sorting: ";
    printArray(arr, size);

    bringMinElementToFront(arr, size);

    std::cout << "Array after bringing the min element to the front: ";
    printArray(arr, size);

    bubbleSort(arr, size);

    std::cout << "Array after sorting using bubble sort: ";
    printArray(arr, size);

    delete[] arr;

    return 0;
}
