    {
        if (address >= IMG_LowAddress(img) && address <= IMG_HighAddress(img))
        {
            moduleBase = IMG_StartAddress(img);
            break;
        }
    }
}

VOID PrintOffset(ADDRINT readAddress, ADDRINT moduleBase)
{
