Certainly! Here's an example implementation of the infix to RPN conversion using the Shunting Yard algorithm in C++:

```cpp
#include <iostream>
#include <stack>
#include <string>
#include <sstream>

bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

int getPrecedence(char c) {
    if (c == '+' || c == '-')
        return 1;
    else if (c == '*' || c == '/')
        return 2;
    return 0;
}

std::string infixToRPN(const std::string& infix) {
    std::stringstream ss(infix);
    std::string token;
    std::stack<char> operatorStack;
    std::string output;

    while (ss >> token) {
        if (isdigit(token[0]) || isalpha(token[0])) { // Operand
            output += token + " ";
        }
        else if (isOperator(token[0])) { // Operator
            while (!operatorStack.empty() && operatorStack.top() != '(' &&
                   getPrecedence(operatorStack.top()) >= getPrecedence(token[0])) {
                output += operatorStack.top();
                output += ' ';
                operatorStack.pop();
            }
            operatorStack.push(token[0]);
        }
        else if (token[0] == '(') { // Opening parenthesis
            operatorStack.push(token[0]);
        }
        else if (token[0] == ')') { // Closing parenthesis
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                output += operatorStack.top();
                output += ' ';
                operatorStack.pop();
            }
            operatorStack.pop(); // Discard the opening parenthesis
        }
    }

    // Pop any remaining operators from the stack
    while (!operatorStack.empty()) {
        output += operatorStack.top();
        output += ' ';
        operatorStack.pop();
    }

    return output;
}

int main() {
    std::string infixExpression = "(5+2)*7";
    std::string rpnExpression = infixToRPN(infixExpression);

    std::cout << "Infix Expression: " << infixExpression << std::endl;
    std::cout << "RPN Expression: " << rpnExpression << std::endl;

    return 0;
}
```

Output:
```
Infix Expression: (5+2)*7
RPN Expression: 5 2 + 7 *
```

In this example, we define the `isOperator()` function to check if a character is an operator, and the `getPrecedence()` function to get the precedence of an operator. The `infixToRPN()` function takes an infix expression as input and returns the equivalent RPN expression.

We iterate through each token in the input expression, which we split using a `std::stringstream`. If the token is an operand, it is directly appended to the output string. If the token is an operator or parenthesis, we handle it based on the Shunting Yard algorithm's rules. Operators on top of the stack with higher or equal precedence are popped and appended to the output string.

The resulting RPN expression is then returned.

Note that this implementation assumes a single-digit operand and does not handle negative numbers or unary operators. You may need to modify the implementation based on your specific requirements.

