To print all elements of `std::stack<std::string>` without popping each element, you can make use of a temporary stack to store the elements, and then restore them back to the original stack after printing. Here's an example:

```cpp
#include <iostream>
#include <stack>
#include <string>

void printStackElements(std::stack<std::string>& myStack) {
    std::stack<std::string> tempStack;

    // Transfer elements from the original stack to the temporary stack
    while (!myStack.empty()) {
        tempStack.push(myStack.top());
        myStack.pop();
    }

    // Print the elements from the temporary stack
    while (!tempStack.empty()) {
        std::cout << tempStack.top() << std::endl;
        tempStack.pop();
    }

    // Restore the elements back to the original stack
    while (!tempStack.empty()) {
        myStack.push(tempStack.top());
        tempStack.pop();
    }
}

int main() {
    std::stack<std::string> myStack;
    myStack.push("Hello");
    myStack.push("World");
    myStack.push("!");

    printStackElements(myStack);

