        public List<string> GetAllMailboxes()
        {
            List<string> mailboxes = new List<string>();

            // Получение списка всех почтовых ящиков
            SendCommand($"{GenerateTag()} LIST \"\" \"*\"\r\n");
            _response = ReadResponse();
            _response = _response.Remove(_response.LastIndexOf($"A{_currentTagNumber:000}"));

            // Разбор ответа и извлечение имен почтовых ящиков
            var matches = Regex.Matches(_response, @"(?<=\s""|\s)\w*(?:[\.\s/\-\*\&+'$\\#,]\w*)*(?=""\r|\r)", RegexOptions.Multiline);
            foreach (Match match in matches)
            {
                string mailbox = match.Value;
                mailboxes.Add(mailbox);
            }

            return mailboxes;
        }

