#include <stdio.h>
#include <stdlib.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>

void multiply_matrices(double* A, double* B, double* C, int m, int n, int k)
{
    int lda = m;
    int ldb = k;
    int ldc = m;

    double alpha = 1.0;
    double beta = 0.0;

    cublasHandle_t handle;
    cublasCreate(&handle);

    cublasDgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, m, n, k, 
                &alpha, A, lda, B, ldb, &beta, C, ldc);

    cublasDestroy(handle);
}

int main()
{
    int m = 3; // rows of A and C
    int n = 2; // columns of B and C
    int k = 4; // columns of A and rows of B

    double* h_A = (double*)malloc(m * k * sizeof(double));
    double* h_B = (double*)malloc(k * n * sizeof(double));
    double* h_C = (double*)malloc(m * n * sizeof(double));

    // Fill input matrices A and B with desired values

    // Allocate device memory
    double* d_A, * d_B, * d_C;
    cudaMalloc(&d_A, m * k * sizeof(double));
    cudaMalloc(&d_B, k * n * sizeof(double));
    cudaMalloc(&d_C, m * n * sizeof(double));

    // Copy input matrices to device
    cudaMemcpy(d_A, h_A, m * k * sizeof(double), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, k * n * sizeof(double), cudaMemcpyHostToDevice);

    // Perform matrix multiplication
    multiply_matrices(d_A, d_B, d_C, m, n, k);

    // Copy result matrix C from device to host
    cudaMemcpy(h_C, d_C, m * n * sizeof(double), cudaMemcpyDeviceToHost);

    // Free device memory
    cudaFree(d_A);
    cudaFree(d_B);
