                var imapPort = imapServer?.Element("port")?.Value;

                var pop3Server = xdoc.Descendants("incomingServer").FirstOrDefault(e => (string)e.Attribute("type") == "pop3");
                var pop3Host = pop3Server?.Element("hostname")?.Value;
                var pop3Port = pop3Server?.Element("port")?.Value;

                if (imapHost != null || pop3Host != null)
                {
                    var domainSettings = new DomainSettings()
                    {
                        Domain = domain,
                        ImapHostname = imapHost,
                        ImapPort = int.TryParse(imapPort, out var imapResult) ? imapResult : (int?)null,
                        PopHostname = pop3Host,
                        PopPort = int.TryParse(pop3Port, out var popResult) ? popResult : (int?)null
                    };

                    _isFound = true;

                    return domainSettings;
                }

                return null;
            }
            catch
            {
                return null;
            }
        }

