        {
            return $"A{++_currentTagNumber:000}";
        }

        public void Connect()
        {
            int retryCount = 0;
            const int MaxRetries = 30;

            while (retryCount < MaxRetries)
            {
                try
                {
                    if (UseProxyConnection(out TcpClient client))
                    {
                        HandleImapConnection(client);
                        return;
                    }
                }
                catch (Exception e)
                {
                    if (e is SocketException)
                    {
                        _account.Result = Result.WrongServer;
                        return;
                    }

                    _account.Errors++;
                    if (_account.Errors >= MaxRetries)
                    {
                        _account.Result = Result.Error;
                        return;
                    }

                    retryCount++;
                }
            }
        }

        private bool UseProxyConnection(out TcpClient client)
        {
            client = null;
            try
            {
                client = ProxyConnectionFactory.CreateClient(_proxyType, _account.Server, _account.Port);
                if (client == null)
                {
                    return false;
                }

                if (_account.Port == 993)
                {
                    UseSsl(client);
                }

                Authenticate(client);
                return true;
            }
            catch
            {
                client?.Dispose();
                throw;
            }
        }

        private void UseSsl(TcpClient client)
        {
            var sslStream = new SslStream(client.GetStream(), false, new RemoteCertificateValidationCallback(ValidateServerCertificate), null);
            sslStream.AuthenticateAsClient(_account.Server);

            using var reader = new StreamReader(sslStream);
            using var writer = new StreamWriter(sslStream);

            _response = ReadResponse(reader);
            if (!IsServerResponseOK(_response))
            {
                throw new InvalidOperationException("SSL authentication failed.");
            }
        }

        private void Authenticate(TcpClient client)
