            FullData = fullData;
            Email = dataParts[0];
            Password = dataParts[1];
            Errors = 0;
            Result = Result.ToCheck;
        }

        public bool SetServer()
        {
            try
            {
                string md5 = EncryptDomain(Domain);

                if (TrySetServerSettingsFromDatabase(md5, "IMAP") || TrySetServerSettingsFromDatabase(md5, "POP3"))
                {
                    return true;
                }

                AddDomainToSearchSettingsQueue(Domain);
                return false;
            }
            catch (Exception ex)
            {
                AddDomainToSearchSettingsQueue(Domain);
                // Optionally, log the exception for further inspection.
                return false;
            }
        }

        private bool TrySetServerSettingsFromDatabase(string md5, string serverType)
        {
            var connectionString = serverType == "IMAP" ? Sqlite.SQLiteConnectionImap : Sqlite.SQLiteConnectionPop3;
            using (var connection = new SqliteConnection(connectionString))
            {
                connection.Open();
                using (var command = connection.CreateCommand())
                {
                    command.CommandText = $"SELECT Server, Port FROM Servers WHERE DomainMd5 = @DomainMd5";
                    command.Parameters.AddWithValue("@DomainMd5", md5);

                    using (var reader = command.ExecuteReader())
                    {
                        if (!reader.Read()) return false;

                        Type = serverType;
                        Server = reader.GetString(0);
                        Port = reader.GetInt32(1);
                        return true;
                    }
                }
            }
        }

        private void AddDomainToSearchSettingsQueue(string domain)
        {
            ViewManager.MainWindow.DomainsForSearchSettings.Add(domain);
        }

        private static string EncryptDomain(string domain)
        {
            return MD5Helper.Encrypt(domain + "985B5C1D89379FBD141A86AE97169D63").ToUpper();
        }
    }
}
