```java
public class MainActivity extends AppCompatActivity {

    private SharedPreferences sharedPreferences;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        RadioButton sedan = findViewById(R.id.sedan);
        RadioButton suv = findViewById(R.id.suv);
        RadioButton mv = findViewById(R.id.mv);
        Button button = findViewById(R.id.next);

        sharedPreferences = getSharedPreferences("car_types", Context.MODE_PRIVATE);

        button.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                String selectedCarType = "";

                if (sedan.isChecked()) {
                    selectedCarType = "Sedan";
                } else if (suv.isChecked()) {
                    selectedCarType = "SUV";
                } else if (mv.isChecked()) {
                    selectedCarType = "Minivan";
                }

                // Save preferences
                SharedPreferences.Editor editor = sharedPreferences.edit();
                editor.putString("selected_car", selectedCarType);
                editor.apply();

                Intent intent = new Intent(MainActivity.this, SavedPreference.class);
                startActivity(intent);
            }
        });
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_main, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        int itemId = item.getItemId();

        if (itemId == R.id.about) {
            showDialogAbout();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }

    private void showDialogAbout() {
        Dialog dialog = new Dialog(MainActivity.this);
        dialog.setContentView(R.layout.dialog_about);
        dialog.setTitle("About");

        TextView aboutText = dialog.findViewById(R.id.about_text);
        aboutText.setText("This is the car rental app.");

