public class CarRental {
    private String renterName;
    private String zipCode;
    private String carSize;
    private double dailyRentalFee;
    private int rentalLength;
    private double totalRentalFee;

    public CarRental(String renterName, String zipCode, String carSize, int rentalLength) {
        this.renterName = renterName;
        this.zipCode = zipCode;
        this.carSize = carSize;
        this.rentalLength = rentalLength;

        if (carSize.equals("economy")) {
            this.dailyRentalFee = 29.99;
        } else if (carSize.equals("midsize")) {
            this.dailyRentalFee = 38.99;
        } else if (carSize.equals("full size")) {
            this.dailyRentalFee = 43.50;
        }

        this.totalRentalFee = dailyRentalFee * rentalLength;
    }

    public void display() {
        System.out.println("Renter's Name: " + renterName);
        System.out.println("Zip Code: " + zipCode);
        System.out.println("Car Size: " + carSize);
        System.out.println("Daily Rental Fee: $" + dailyRentalFee);
        System.out.println("Rental Length (days): " + rentalLength);
        System.out.println("Total Rental Fee: $" + totalRentalFee);
    }
}
