public class ImageDownloader {
    public static void main(String[] args) {
        String url = "https://ya.ru/images/search?from=tabbar&text=%D0%BF%D0%B8%D0%BB%D0%B8%D0%B3%D1%80%D0%B8%D0%BC%20%D0%B4%D1%80%D0%BE%D0%BD";
        List<String> imageUrls = getImageUrls(url);

        downloadImages(imageUrls, 200, "Piligrim/");
