    private static List<String> getImageUrls(String url) {
        List<String> imageUrls = new ArrayList<>();

        try {
            Document doc = Jsoup.connect(url).get();
            Elements imageElements = doc.getElementsByTag("img");

            for (Element imageElement : imageElements) {
                String imageUrl = imageElement.absUrl("src");
                if (!imageUrl.isEmpty()) {
                    imageUrls.add(imageUrl);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return imageUrls;
    }

    private static void downloadImages(List<String> imageUrls, int limit, String outputDir) {
        int count = 0;

        for (String imageUrl : imageUrls) {
            if (count >= limit) {
                break;
            }

            try (CloseableHttpClient httpClient = HttpClientBuilder.create().build()) {
                HttpGet request = new HttpGet(imageUrl);
                HttpResponse response = httpClient.execute(request);
                long contentLength = response.getEntity().getContentLength();

                if (contentLength > 0) {
                    URL url = new URL(imageUrl);
                    URLConnection connection = url.openConnection();
                    connection.setRequestProperty("Range", "bytes=0-" + (contentLength - 1));

                    InputStream inputStream = connection.getInputStream();

                    byte[] buffer = new byte[4096];
                    int bytesRead;

                    String extension = imageUrl.substring(imageUrl.lastIndexOf("."));
                    File output = new File(outputDir + count + extension);
                    FileOutputStream fos = new FileOutputStream(output);

                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        fos.write(buffer, 0, bytesRead);
                    }

                    fos.close();
                    inputStream.close();

                    count++;
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
