		LbEndpoints = append(LbEndpoints, LbEndpoint)
	}

	clusterName := GenerateClusterName(dr.Spec.Source, dr.Spec.Destination)
	loadAssignment := &endpoint.ClusterLoadAssignment{
		ClusterName: clusterName,
