Certainly! Here are examples of usage for some commonly used React hooks:

1. useState: to manage state in a functional component.

```javascript
import React, { useState } from 'react';

const Counter = () => {
  const [count, setCount] = useState(0);

  const increment = () => {
    setCount(count => count + 1);
  };

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={increment}>Increment</button>
    </div>
  );
};

export default Counter;
```

2. useEffect: to perform side effects (e.g., data fetching, subscriptions) in a functional component.

```javascript
import React, { useState, useEffect } from 'react';

const UserProfile = ({ userId }) => {
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Simulating API call to fetch user data
    const fetchUser = async () => {
      const response = await fetch(`https://api.example.com/user/${userId}`);
      const data = await response.json();
      setUser(data);
    };

    fetchUser();

    return () => {
      // Cleanup function
      // e.g., cancel subscriptions, clear timers, etc.
    };
  }, [userId]);

  if (!user) {
    return <p>Loading user...</p>;
  }

  return (
    <div>
      <h2>{user.name}</h2>
      <p>Email: {user.email}</p>
    </div>
  );
};

export default UserProfile;
```

3. useContext: to access and update a shared context in a functional component.

```javascript
import React, { useContext } from 'react';

// Create a context
const MyContext = React.createContext();

const MyComponent = () => {
  // Access the value from the context
  const value = useContext(MyContext);

  return <p>Value from context: {value}</p>;
};

const App = () => {
  return (
    // Provide a value to the context
    <MyContext.Provider value="Hello, Context!">
      <MyComponent />
    </MyContext.Provider>
  );
};

export default App;
```

