```cpp
#include <Eigen/Sparse>

Eigen::SparseMatrix<size_t> combineMatrixBlocks(const std::vector<Eigen::SparseMatrix<size_t>>& matrix_blocks, const std::vector<size_t>& order) {
    if (matrix_blocks.empty() || order.empty())
        throw std::invalid_argument("Invalid input: matrix_blocks or order is empty.");

    size_t nrows = matrix_blocks[order[0]].rows();
    size_t ncols = matrix_blocks[order[0]].cols();

    for (size_t i = 1; i < order.size(); ++i) {
        if (matrix_blocks[order[i]].rows() != nrows || matrix_blocks[order[i]].cols() != ncols)
            throw std::invalid_argument("Invalid input: matrix_blocks have different sizes.");
    }

    Eigen::SparseMatrix<size_t> result(nrows * order.size(), ncols);

    for (size_t i = 0; i < order.size(); ++i) {
        size_t row_offset = i * nrows;
        result.block(row_offset, 0, nrows, ncols) = matrix_blocks[order[i]];
    }

    return result;
}
