Finally, create a custom adapter to bind data to the parent `ListView`:
```java
public class CustomAdapter extends BaseAdapter {

    private LayoutInflater inflater;
    private List<List<String>> parentList;
    private Context context;

    public CustomAdapter(Context context, List<List<String>> parentList) {
        this.context = context;
        this.parentList = parentList;
        inflater = LayoutInflater.from(context);
    }

    @Override
    public int getCount() {
        return parentList.size();
    }

    @Override
    public Object getItem(int position) {
        return parentList.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        ViewHolder holder;

        if (convertView == null) {
            convertView = inflater.inflate(R.layout.row_item, parent, false);

            holder = new ViewHolder();
            holder.childListView = convertView.findViewById(R.id.childListView);
            convertView.setTag(holder);
        } else {
            holder = (ViewHolder) convertView.getTag();
        }

        // Bind child data to the child ListView
        ChildAdapter childAdapter = new ChildAdapter(context, parentList.get(position));
        holder.childListView.setAdapter(childAdapter);

        return convertView;
    }

    static class ViewHolder {
        ListView childListView;
    }
}
```

