const courses = {};

for (let i = 0; i < grades.length; i++) {
    const courseName = grades[i].courseName;
    const grade = grades[i].grade;

    if (!courses[courseName]) {
        courses[courseName] = {
            max: grade,
            min: grade,
            sum: grade,
            count: 1,
        };
    } else {
        if (grade > courses[courseName].max) {
            courses[courseName].max = grade;
        }
        if (grade < courses[courseName].min) {
            courses[courseName].min = grade;
        }
        courses[courseName].sum += grade;
        courses[courseName].count++;
