// Function to normalize the puzzle map
void normalizePuzzleMap(int width, char puzzleMap[][MAX_WIDTH])
{
    char nextChar = 'A';

    for (int y = 0; y < width; y++)
    {
        for (int x = 0; x < width; x++)
        {
            if (puzzleMap[x][y] != ' ')
                puzzleMap[x][y] = nextChar;
        }
    }
}

// Recursive function to fill the puzzle map
void fillPuzzleRecursive(int width, char puzzleMap[][MAX_WIDTH], int tx, int ty, int x, int y, char &nextChar)
{
    if (width == 2)
    {
        puzzleMap[tx + 1][ty] = nextChar++;
        puzzleMap[tx + 1][ty + 1] = nextChar++;
        puzzleMap[tx][ty + 1] = nextChar++;

        if (x == tx && y == ty)
            puzzleMap[tx][ty] = ' ';

        return;
    }

    int halfWidth = width / 2;
    int quad = locateQuadrant(width, x, y);
    nextChar += 4;

    if (quad == 1)
    {
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty, x, y, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty, tx + halfWidth, ty + halfWidth, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty + halfWidth, tx + halfWidth, ty + halfWidth, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty + halfWidth, tx + halfWidth - 1, ty + halfWidth, nextChar);
    }
    else if (quad == 2)
    {
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty, tx + halfWidth, ty + halfWidth - 1, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty, x, y, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty + halfWidth, tx + halfWidth, ty + halfWidth, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty + halfWidth, tx + halfWidth, ty + halfWidth, nextChar);
    }
    else if (quad == 3)
    {
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty, tx + halfWidth, ty + halfWidth - 1, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty + halfWidth, x, y, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty, tx + halfWidth - 1, ty + halfWidth, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx, ty + halfWidth, tx + halfWidth, ty + halfWidth, nextChar);
    }
    else if (quad == 4)
    {
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty, tx + halfWidth, ty + halfWidth - 1, nextChar);
        fillPuzzleRecursive(halfWidth, puzzleMap, tx + halfWidth, ty + halfWidth, tx + halfWidth - 1, ty + halfWidth, nextChar);
