    TamingTime = 5.0f;
}

void ATameablePet::BeginPlay()
{
    Super::BeginPlay();

    // Bind overlap function to the OnActorBeginOverlap event
    OnActorBeginOverlap.AddDynamic(this, &ATameablePet::OnTamingZoneOverlap);
}

void ATameablePet::Tick(float DeltaTime)
{
    Super::Tick(DeltaTime);

    if (bIsTaming)
    {
        TamingProgress += DeltaTime;
        if (TamingProgress >= TamingTime)
        {
            Tame();
        }
    }
}

void ATameablePet::OnTamingZoneOverlap(AActor* OverlappedActor, AActor* OtherActor)
{
    APlayerCharacter* PlayerCharacter = Cast<APlayerCharacter>(OtherActor);
    if (PlayerCharacter)
    {
        StartTaming();
    }
}

void ATameablePet::StartTaming()
{
    bIsTaming = true;
}

void ATameablePet::Tame()
{
    bIsTaming = false;
    OnTamed.Broadcast();
    // Add the pet to the player's inventory or assign it as a companion, etc.
}
