void splitName(char fullName[], char firstName[], char lastName[]) {
    int i, j;

    for(i = 0; fullName[i] != ' '; i++) {
        firstName[i] = fullName[i];
    }
    firstName[i] = '\0';

    for(j = 0, i += 1; fullName[i] != '\0'; i++, j++) {
