Here's an example of a C# console menu with the specified choices:

```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        bool exit = false;
        ItemList itemList = new ItemList();

        while (!exit)
        {
            Console.Clear();
            Console.WriteLine("Menu:");
            Console.WriteLine("1. Add Item");
            Console.WriteLine("2. Delete by ID");
            Console.WriteLine("3. Print All");
            Console.WriteLine("4. Exit");

            Console.Write("Enter your choice: ");
            string choice = Console.ReadLine();

            switch (choice)
            {
                case "1":
                    Console.Write("Enter item ID: ");
                    int id = int.Parse(Console.ReadLine());
                    Console.Write("Enter item name: ");
                    string name = Console.ReadLine();

                    Item item = new Item(id, name);
                    itemList.AddItem(item);
                    break;

                case "2":
                    Console.Write("Enter item ID to delete: ");
                    int deleteId = int.Parse(Console.ReadLine());

                    itemList.DeleteById(deleteId);
                    break;

                case "3":
                    itemList.PrintAll();
                    break;

                case "4":
                    exit = true;
                    break;

                default:
                    Console.WriteLine("Invalid choice. Please try again.");
                    break;
            }

            Console.WriteLine("Press any key to continue...");
            Console.ReadKey();
        }

        Console.WriteLine("Exiting the program...");
    }
}

class Item
{
    public int ID { get; set; }
    public string Name { get; set; }

    public Item(int id, string name)
    {
        ID = id;
        Name = name;
    }
}

class ItemList
{
    private List<Item> items;

    public ItemList()
    {
        items = new List<Item>();
    }

    public void AddItem(Item item)
    {
        items.Add(item);
        Console.WriteLine("Item added successfully.");
    }

    public void DeleteById(int id)
    {
        Item item = items.FirstOrDefault(i => i.ID == id);

        if (item != null)
        {
            items.Remove(item);
            Console.WriteLine("Item deleted successfully.");
        }
        else
        {
            Console.WriteLine("No item found with the provided ID.");
        }
    }

    public void PrintAll()
    {
        Console.WriteLine("Items:");

        foreach (Item item in items)
        {
            Console.WriteLine($"ID: {item.ID}, Name: {item.Name}");
        }
    }
}
```

This example uses a `ItemList` class to store and manage the items. The `Item` class represents an individual item with an ID and a name. The main program presents a menu with options to add an item, delete an item by ID, print all the items, or exit the program. Based on the user's choice, the program interacts with the `ItemList` to perform the specified action.

Sure! To implement a data structure capable of holding 128 binary values (booleans) using bitwise operations, you can use an array of 4 integers (each with a size of 32 bits) to store the values. Here's an example implementation in C:

```c
#include <stdio.h>
#include <stdbool.h>

#define SIZE 128
#define INT_SIZE 32

typedef struct {
    unsigned int data[4];
} BitArray;

// Function to initialize the bit array
void initialize(BitArray* array) {
    for (int i = 0; i < 4; i++) {
        array->data[i] = 0;
    }
}

// Function to set a value at a particular index
void set(BitArray* array, int index, bool value) {
    if (index >= 0 && index < SIZE) {
        int block = index / INT_SIZE;   // Determine the block index
        int bit = index % INT_SIZE;     // Determine the bit index within the block

        if (value) {
            array->data[block] |= (1U << bit);  // Set the bit to 1
        } else {
            array->data[block] &= ~(1U << bit); // Set the bit to 0
        }
    }
}

// Function to get a value at a particular index
bool get(BitArray* array, int index) {
    if (index >= 0 && index < SIZE) {
        int block = index / INT_SIZE;   // Determine the block index
        int bit = index % INT_SIZE;     // Determine the bit index within the block

        return (array->data[block] >> bit) & 1U;  // Retrieve the bit value
    }

    return false; // Default value if index is out of range
}

// Function to display the bit array
void display(BitArray* array) {
    for (int i = SIZE - 1; i >= 0; i--) {
        printf("%d", get(array, i));
    }
    printf("\n");
}

int main() {
    BitArray bitArray;
    initialize(&bitArray);

    set(&bitArray, 0, true);
    set(&bitArray, 2, true);
    set(&bitArray, 5, true);
    set(&bitArray, 7, true);

    display(&bitArray);  // Output: 10100101

    return 0;
}
```

In the above code, we define a `BitArray` structure that holds the 128 binary values. The `initialize()` function sets all bits in the `BitArray` to 0. The `set()` function allows you to set a specific index to either true or false using bitwise operations. The `get()` function retrieves the value at a specific index. Finally, the `display()` function prints the binary representation of the `BitArray`.

In the `main()` function, we demonstrate how to use the implemented data structure by setting some bits and displaying the resulting binary representation.

