#define hidden_size 200
#define seq_length 50
#define learning_rate 0.1

double random_double() {
    return (double)rand() / (double)RAND_MAX;
}

void forwardPass(int* inputs, int* targets, double* hprev, double* Wxh, double* Whh, double* Why, double* bh, double* by, int vocab_size, double** xs, double** hs, double** ys, double** ps, double* loss) {
    for (int t = 0; t < seq_length; t++) {
        for (int i = 0; i < vocab_size; i++) {
            xs[t][i] = 0.0;
        }
        xs[t][inputs[t]] = 1.0;

        hs[t] = (double*)malloc(hidden_size * sizeof(double));
        for (int i = 0; i < hidden_size; i++) {
            hs[t][i] = 0.0;
        }

        for (int i = 0; i < hidden_size; i++) {
            for (int j = 0; j < vocab_size; j++) {
                hs[t][i] += Wxh[i * vocab_size + j] * xs[t][j];
            }
            if (t > 0) {
                for (int j = 0; j < hidden_size; j++) {
                    hs[t][i] += Whh[i * hidden_size + j] * hs[t - 1][j];
                }
            }
            hs[t][i] += bh[i];
            hs[t][i] = tanh(hs[t][i]);
        }

        ys[t] = (double*)malloc(vocab_size * sizeof(double));
        for (int i = 0; i < vocab_size; i++) {
            ys[t][i] = 0.0;
        }

        for (int i = 0; i < vocab_size; i++) {
            for (int j = 0; j < hidden_size; j++) {
                ys[t][i] += Why[i * hidden_size + j] * hs[t][j];
            }
            ys[t][i] += by[i];
        }

        ps[t] = (double*)malloc(vocab_size * sizeof(double));
        for (int i = 0; i < vocab_size; i++) {
            ps[t][i] = exp(ys[t][i]);
        }
        double sum_exp = 0.0;
        for (int i = 0; i < vocab_size; i++) {
            sum_exp += ps[t][i];
        }
        for (int i = 0; i < vocab_size; i++) {
            ps[t][i] /= sum_exp;
        }

        *loss += -log(ps[t][targets[t]]);
    }
}

void backwardPass(int* inputs, int* targets, double** xs, double** hs, double** ps, double* Wxh, double* Whh, double* Why, double* bh, double* by, int vocab_size, double* dWxh, double* dWhh, double* dWhy, double* dbh, double* dby) {
