    public class Account
    {
        public string Type { get; set; }
        public string Email { get; }
        public string Password { get; }
        public string Domain => Email.Substring(Email.IndexOf("@", StringComparison.Ordinal) + 1);
        public int Errors { get; set; }
        public Result Result { get; set; }
        public string Server { get; private set; }
        public int Port { get; private set; }

        public Account(string fullData)
        {
            var dataParts = fullData.Split(':', 2);
            if (dataParts.Length != 2)
            {
                throw new ArgumentException("Full data must be in 'email:password' format.", nameof(fullData));
            }

            Email = dataParts[0];
            Password = dataParts[1];
            Errors = 0;
            Result = Result.ToCheck;
        }

        public bool SetServer()
        {
            try
            {
                string md5 = MD5Helper.Encrypt($"{Domain}985B5C1D89379FBD141A86AE97169D63").ToUpper();
                return RetrieveServerSettings(md5, "IMAP") || RetrieveServerSettings(md5, "POP3");
            }
            catch
            {
                ViewManager.MainWindow.DomainsForSearchSettings.Add(Domain);
                return false;
            }
        }

        private bool RetrieveServerSettings(string md5, string serverType)
        {
            var connection = serverType == "IMAP" ? SQLite.sqLiteConnectionImap : SQLite.sqLiteConnectionPop3;
            var preparedQuery = $"SELECT Server, Port, Socket FROM '{md5[0]}' WHERE Domain = @Domain LIMIT 1;";

            using (var sqLiteCommand = new SqliteCommand(preparedQuery, connection))
            {
                sqLiteCommand.Parameters.AddWithValue("@Domain", md5);
                using (var sqLiteDataReader = sqLiteCommand.ExecuteReader())
                {
                    if (!sqLiteDataReader.Read())
                    {
                        return false;
                    }

                    Type = serverType;
                    Server = sqLiteDataReader.GetString(0);
                    Port = sqLiteDataReader.GetInt32(1);
                    return true;
                }
            }
        }
    }
}
