```csharp
using System;
using Microsoft.Data.Sqlite;

namespace EmailSoftWare.Models.UserData
{
    public class Account
    {
        private const string Md5Suffix = "985B5C1D89379FBD141A86AE97169D63";
        private const string IMAP = "IMAP";
        private const string POP3 = "POP3";

        public string Type { get; private set; }
        public string FullData { get; private set; }
        public string Email { get; private set; }
        public string Password { get; private set; }
        public string Domain { get; private set; }
        public int Errors { get; set; }
        public Result Result { get; set; }
        public string Server { get; private set; }
        public int Port { get; private set; }

        public Account(string fullData)
        {
            if (string.IsNullOrWhiteSpace(fullData))
                throw new ArgumentException($"'{nameof(fullData)}' cannot be null or whitespace.", nameof(fullData));

            var dataParts = fullData.Split(":");
            if (dataParts.Length < 2)
                throw new FormatException("The account fullData must contain an email and a password separated by a colon.");

            FullData = fullData;
            Email = dataParts[0];
            Password = dataParts[1];
            Errors = 0;
            Result = Result.ToCheck;
        }

        public bool TrySetServerSettings()
        {
            string[] emailParts = Email.Split("@");
            if (emailParts.Length != 2) return false;
            Domain = emailParts[1];

            string md5 = MD5Helper.Encrypt(Domain + Md5Suffix).ToUpper();

            if (TryRetrieveServerSettings(md5, IMAP) || TryRetrieveServerSettings(md5, POP3))
            {
                return true;
            }

            AddDomainToSearchSettings(Domain);

            return false;
        }

        private bool TryRetrieveServerSettings(string md5, string serverType)
        {
            string tableName = md5[0].ToString();
            try
            {
                using var sqLiteCommand = new SqliteCommand($"SELECT Server, Port, Socket FROM {tableName} WHERE Domain = @md5", 
                    serverType == IMAP ? SQLite.sqLiteConnectionImap : SQLite.sqLiteConnectionPop3);
                sqLiteCommand.Parameters.AddWithValue("@md5", md5);

                using var sqLiteDataReader = sqLiteCommand.ExecuteReader();
                if (!sqLiteDataReader.Read()) return false;

                Type = serverType;
                Server = sqLiteDataReader.GetString(0);
                Port = sqLiteDataReader.GetInt32(1);
                return true;
            }
            catch
            {
                AddDomainToSearchSettings(Domain);
                return false;
            }
        }

        private void AddDomainToSearchSettings(string domain)
        {
            MainWindow.DomainsForSearchSettings.Add(domain);
        }
    }
}
