fn main() -> Result<(), Box<dyn std::error::Error>> {
    let source_address = "srt://source_ip:source_port";
    let target_address = "srt://target_ip:target_port";
    let stream_id = "your_unique_stream_id"; // The unique stream ID you want to use

    // Create an SRT receiver socket with a particular stream ID.
    let mut receiver = SrtSocketBuilder::new_listen()
        .local_port(source_address.parse().unwrap().port())
        .stream_id(stream_id.to_string()) // Setting the stream ID here
        .connect()?;

    // Create an SRT sender socket, possibly with a different stream ID if needed
    let mut sender = SrtSocketBuilder::new_connect()
        .remote(target_address.parse().unwrap())
        // Assuming we want to use the same stream ID for the sender
        .stream_id(stream_id.to_string()) // Setting the stream ID here
        .connect()?;

    let mut buffer = [0; 1316]; // SRT typically works with 1316 bytes packets for MPEG-TS

    loop {
        match receiver.recv_from(&mut buffer) {
            Ok((size, _source)) => {
                // Forward the received data to the target, along with the stream ID
                sender.send_to(&buffer[..size], &target_address.parse().unwrap())?;
            },
            Err(e) => {
                eprintln!("Error receiving data: {}", e);
                break;
            }
        }
    }

    Ok(())
}
