void forward_pass(char *input_sequence, double *hprev, double *loss) {
    double xs[SEQ_LENGTH][VOCAB_SIZE]; // Input sequence
    double hs[SEQ_LENGTH + 1][HIDDEN_SIZE]; // Hidden states
    double ys[SEQ_LENGTH][VOCAB_SIZE]; // Output probabilities
    double ps[SEQ_LENGTH][VOCAB_SIZE]; // Output values after softmax

    // Initialize hidden state
    for (int i = 0; i < HIDDEN_SIZE; ++i) {
        hs[0][i] = hprev[i];
    }

    // Forward pass for each character in the input sequence
    for (int t = 0; t < SEQ_LENGTH; ++t) {
        one_hot_encode(input_sequence[t], xs[t]);

        // Hidden state calculation
        for (int i = 0; i < HIDDEN_SIZE; ++i) {
            double sum = 0.0;
            for (int j = 0; j < VOCAB_SIZE; ++j) {
                sum += Wxh[i][j] * xs[t][j];
            }
            sum += bh[i];
            hs[t + 1][i] = tanh(sum);
        }

        // Output calculation
        for (int i = 0; i < VOCAB_SIZE; ++i) {
            double sum = 0.0;
            for (int j = 0; j < HIDDEN_SIZE; ++j) {
                sum += Why[i][j] * hs[t + 1][j];
            }
            sum += by[i];
            ys[t][i] = sum;
            ps[t][i] = softmax(ys[t], VOCAB_SIZE, i);
        }
    }

    // Calculate loss
    *loss = 0.0;
    for (int t = 0; t < SEQ_LENGTH; ++t) {
        *loss += -log(ps[t][input_sequence[t]]);
    }
}
