#include <iostream>
#include <tuple>
#include <vector>

std::tuple<int, int, int, int> get_intersection(int qx, int qy, int qwidth, int qheight,
                                                 int x, int y, int width, int height) {
    int intersection_left = std::max(x, qx);
    int intersection_top = std::max(y, qy);
    int intersection_right = std::min(x + width, qx + qwidth);
    int intersection_bottom = std::min(y + height, qy + qheight);

    return std::make_tuple(intersection_left, intersection_top,
                           intersection_right - intersection_left,
                           intersection_bottom - intersection_top);
}

bool has_positive_area(int x, int y, int width, int height) {
    return width > 0 && height > 0;
}

bool intersect(std::tuple<int, int, int, int> q_bbox, std::tuple<int, int, int, int> bounding_box) {
    int x, y, width, height;
    std::tie(x, y, width, height) = get_intersection(std::get<0>(q_bbox), std::get<1>(q_bbox), std::get<2>(q_bbox), std::get<3>(q_bbox),
                                                     std::get<0>(bounding_box), std::get<1>(bounding_box), std::get<2>(bounding_box), std::get<3>(bounding_box));
    return has_positive_area(x, y, width, height);
}

int bbox_position(std::tuple<int, int, int, int> bounding_box, int img_width, int img_height) {
    std::vector<std::tuple<int, int, int, int>> quadrants = {
        {0, 0, img_width / 2, img_height / 2},
        {img_width / 2, 0, img_width / 2, img_height / 2},
        {0, img_height / 2, img_width / 2, img_height / 2},
        {img_width / 2, img_height / 2, img_width / 2, img_height / 2}
    };

    std::vector<bool> intersections(4, false);
    bool has_intersection_with_all_quadrants = true;
    for (size_t i = 0; i < quadrants.size(); ++i) {
        intersections[i] = intersect(quadrants[i], bounding_box);
        has_intersection_with_all_quadrants = has_intersection_with_all_quadrants && intersections[i];
    }

    if (has_intersection_with_all_quadrants) {
        return 4;
    }

    std::vector<std::pair<std::string, std::vector<int>>> positions = {
        {"left", {0, 2}},
        {"up", {0, 1}},
        {"right", {1, 3}},
        {"down", {2, 3}}
    };

    for (int idx = 0; idx < positions.size(); ++idx) {
        auto [name, qs] = positions[idx];
        bool has_intersection = false;
        for (int q : qs) {
            has_intersection = has_intersection || intersections[q];
        }
        if (has_intersection) {
            return idx;
        }
    }

    return -1; // Bounding box not found in any position
}

int main() {
    int img_width = 800;
    int img_height = 600;
    std::tuple<int, int, int, int> bbox = {250, 150, 100, 100};

    std::cout << "Bounding box position: " << bbox_position(bbox, img_width, img_height) << std::endl; // It will return 4 if the bbox intersects all four quadrants

    return 0;
}
```

