import numpy as np

def block_order(a):
    n = a.shape[2]
    if len(a.shape) > 3:  # if array has more than 3 dimensions
        b = []
        for k in range(0, a.shape[3]):
            b += block_order(a[:, :, :, k])
        return np.array(b)
    elif n == 2:
        return a.flatten()
    else:
        b = []
        for i in range(0, n, 2):
            for j in range(0, n, 2):
                for k in range(0, n, 2):
                    b.append(a[:, :, i:i+2, j:j+2, k:k+2].flatten())
        return np.array(b)

A = np.random.randint(1, high=100, size=(4, 4, 16, 16))  # generate random input array for testing
