```python
import discord
from discord.ext import commands

class WelcomeCommands(commands.Cog):
    def __init__(self, bot):
        self.bot = bot
        self.db = bot.db #assuming you have a database

    @commands.group(name='welcome', invoke_without_command=True)
    async def welcome(self, ctx):
        await ctx.send(f'Welcome to {ctx.guild}! These are the available subcommands: setup, channel, message, remove.')

    @welcome.command(name='setup')
    @commands.has_permissions(administrator=True)
    async def setup_welcome(self, ctx):
        await ctx.send('Please mention the channel where the welcome messages will be sent:')
        try:
            channel = await self.bot.wait_for('message', timeout=60.0, check=lambda m: m.author == ctx.author and m.channel == ctx.channel and m.mentions)
        except asyncio.TimeoutError:
            return await ctx.send('No channel was mentioned. Setup cancelled')
        await self.db.execute('INSERT INTO welcome_channels (guild_id, channel_id) VALUES (?, ?)', ctx.guild.id, channel.channel.id)
        await ctx.send(f'Channel {channel.channel.mention} has been set as the welcome channel!')

    @welcome.command(name='channel')
    @commands.has_permissions(administrator=True)
    async def set_welcome_channel(self, ctx):
        await ctx.send('Please mention the channel you want to set as the welcome channel:')
        try:
            channel = await self.bot.wait_for('message', timeout=60.0, check=lambda m: m.author == ctx.author and m.channel == ctx.channel and m.mentions)
        except asyncio.TimeoutError:
            return await ctx.send('No channel was mentioned. Set up a welcome channel first using !welcome setup')
        await self.db.execute('UPDATE welcome_channels SET channel_id = ? WHERE guild_id = ?', channel.channel.id, ctx.guild.id)
        await ctx.send(f'Channel {channel.channel.mention} has been set as the welcome channel!')

    @welcome.command(name='message')
    @commands.has_permissions(administrator=True)
    async def set_welcome_message(self, ctx, *, message=None):
        if not message:
            await ctx.send('Please provide a welcome message. Usage: `!welcome message <message>`')
            return
        await self.db.execute('UPDATE welcome_messages SET message = ? WHERE guild_id = ?', message, ctx.guild.id)
        await ctx.send(f'Welcome message set as: {message}')

    @welcome.command(name='remove')
    @commands.has_permissions(administrator=True)
    async def remove_welcome(self, ctx):
        await self.db.execute('DELETE FROM welcome_channels WHERE guild_id = ?', ctx.guild.id)
        await self.db.execute('DELETE FROM welcome_messages WHERE guild_id = ?', ctx.guild.id)
        await ctx.send('Welcome message and channel removed!')

def setup(bot):
    bot.add_cog(WelcomeCommands(bot))
```

