Creating a complete C syntax analyzer using the LL1 analysis method without any external packages involves multiple steps. Below, I'll present a simplified version that can parse arithmetic, assignment, comma, relational and logical expressions. It returns error messages if the analysis fails.

```python
class ParserLL1:
    def __init__(self, grammar):
        self.grammar = grammar
        self.first, self.follow = self.get_first_follow(grammar)
        self.table = self.get_ll1_table(grammar)

    def get_first_follow(self, grammar):
        # Calculate first and follow sets
        first_sets = {}
        follow_sets = {}

        # Initialize first and follow sets
        for non_term in grammar:
            first_sets[non_term] = set()
            follow_sets[non_term] = set()

        # Calculate first sets function
        def calculate_first(item):
            first = set()
            if item in grammar:
                for product in grammar[item]:
                    first.update(calculate_first(product[0]))
            else:
                first.add(item)

            return first

        for non_term in grammar:
            first_sets[non_term] = calculate_first(non_term)

        # Start symbol will have follow $ by default
        follow_sets[next(iter(grammar))].add('$')

        # Calculate follow sets
        change = True
        while change:
            change = False
            for non_term in grammar:
                for product in grammar[non_term]:
                    follow_found = False
                    for item in product:
                        if follow_found:
                            if item in grammar:
                                upd = follow_sets[item].update(first_sets[item].difference({''}))
                                if upd:
                                    change = True
                            follow_found = False
                        if item in grammar:
                            follow_found = True

                    for item in product[::-1]:
                        if item in grammar:
                            upd = follow_sets[item].update(follow_sets[non_term].difference({''}))
                            if upd:
                                change = True
                        else:
                            break

        return first_sets, follow_sets

    def get_ll1_table(self, grammar):
        def get_production_first(prod):
            first = set()
            for item in prod:
                first.update(self.first[item])
                if '' not in self.first[item]:
                    break
            else:
                first.add('')
            return first

        table = {}
        for non_term in grammar:
            table[non_term] = {}
            for prod in grammar[non_term]:
                first = get_production_first(prod)
                for term in first:
                    if term != '':
                        if term in table[non_term]:
                            return None  # Not LL(1) grammar
                        table[non_term][term] = prod

                if '' in first:
                    for term in self.follow[non_term]:
                        if term in table[non_term]:
                            return None  # Not LL(1) grammar
                        if term != '':
                            table[non_term][term] = prod
        return table

    def parse(self, text):
        stack = [list(self.grammar)[0], '$']  # Start symbol
        text += '$'
        index = 0

        while stack:
            stack_top = stack[-1]
            text_top = text[index]

            if text_top == '$' and stack_top == '$':
                return 'Success'

            if stack_top in self.grammar:
                if text_top in self.table[stack_top]:
                    production = self.table[stack_top][text_top]
                    stack.pop()
                    if production != '':
                        for sym in production[::-1]:
                            stack.append(sym)
                else:
                    return f'Error: Unexpected token "{text_top}"'

            elif stack_top == text_top:
                stack.pop()
                index += 1
            else:
                return f'Error: Expected "{stack_top}", got "{text_top}"'

        return 'Error: Premature end of input'

