```python
import numpy as np
import pandas as pd

class Node:
    def __init__(self, is_leaf=False, label=None, feature=None, threshold=None):
        self.is_leaf = is_leaf
        self.label = label
        self.feature = feature
        self.threshold = threshold
        self.left = None
        self.right = None

class HellingerDecisionTree:
    def __init__(self, max_depth=float('inf'), min_samples_split=2, min_samples_leaf=1):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.root = None

    def fit(self, X, y):
        self.root = self._build_tree(X, y, depth=0)

    def predict(self, X):
        y_pred = []
        for i, x in X.iterrows():
            node = self.root
            while not node.is_leaf:
                if x[node.feature] < node.threshold:
                    node = node.left
                else:
                    node = node.right
            y_pred.append(node.label)
        return np.array(y_pred)

    def _build_tree(self, X, y, depth):
        n_samples, n_features = X.shape
        n_classes = len(np.unique(y))

        if depth == self.max_depth \
            or n_samples < self.min_samples_split \
            or len(np.unique(y)) == 1:
            label = self._get_majority_class(y)
            return Node(is_leaf=True, label=label)

        best_feature, best_threshold = self._find_best_split(X, y, n_classes)
        if best_feature is None:
            label = self._get_majority_class(y)
            return Node(is_leaf=True, label=label)

        left_idx = X[best_feature] < best_threshold
        right_idx = X[best_feature] >= best_threshold

        left_node = self._build_tree(X[left_idx], y[left_idx], depth + 1)
        right_node = self._build_tree(X[right_idx], y[right_idx], depth + 1)
        node = Node(feature=best_feature, threshold=best_threshold)
        node.left = left_node
        node.right = right_node

        return node

    def _get_majority_class(self, y):
        classes, counts = np.unique(y, return_counts=True)
        return classes[np.argmax(counts)]

    def _find_best_split(self, X, y, n_classes):
        best_feature, best_threshold, best_metric = None, None, float('inf')
        for i in range(X.shape[1]):
            thresholds = sorted(np.unique(X.iloc[:, i]))
            if len(thresholds) > 1:
                for j in range(len(thresholds) - 1):
                    threshold = (thresholds[j] + thresholds[j + 1]) / 2.0
                    left_idx = X.iloc[:, i] < threshold
                    right_idx = X.iloc[:, i] >= threshold
                    if len(np.unique(y[left_idx])) > 0 and len(np.unique(y[right_idx])) > 0:
                        left_probs = self._class_probs(y[left_idx], n_classes)
                        right_probs = self._class_probs(y[right_idx], n_classes)
                        metric = self._hellinger_distance(left_probs, right_probs)
                        if metric < best_metric:
                            best_metric = metric
                            best_feature = i
                            best_threshold = threshold
        return best_feature, best_threshold

    def _class_probs(self, y, n_classes):
        return np.array([(y == c).mean() for c in range(n_classes)])

    def _hellinger_distance(self, p, q):
        return np.sqrt(np.sum((np.sqrt(p) - np.sqrt(q)) ** 2)) / np.sqrt(2)
```

This implementation defines two classes: `Node` and `HellingerDecisionTree`. The `Node` class represents a node in the decision tree and has attributes for the label, feature, and threshold used to split the data, as well as references to its left and right child nodes. The `HellingerDecisionTree` class contains the main decision tree algorithm and has methods for fitting the tree to the data and making predictions. The `_find_best_split` method is used to find the best feature and threshold value for splitting the data, using the Hellinger distance as the metric. The `fit` method calls `_build_tree` recursively to build the entire tree. The `predict` method follows the tree to make predictions for each input sample.

