The General Number Field Sieve (GNFS) is a complex algorithm used for integer factorization. Here's an outline of a simple Python implementation based on the Quadratic Sieve algorithm, which is a simpler variant of GNFS. Note that this implementation is for educational purposes and may not be efficient for very large integers.

```python
from math import sqrt, gcd

def primes_sieve(limit):
    primes = []
    sieve = [True] * (limit + 1)
    for num in range(2, limit + 1):
        if sieve[num]:
            primes.append(num)
            for multiple in range(num * num, limit + 1, num):
                sieve[multiple] = False
    return primes

def find_factor(base, n):
    B = sqrt(base)
    smooth_primes = primes_sieve(int(B))

    relation_count = len(smooth_primes) + 1
    relations = []

    while len(relations) < relation_count:
        x = int(sqrt(n)) + len(relations)
        Qx = x * x - n

        exponents = []
        for p in smooth_primes:
            e = 0
            while Qx % p == 0:
                Qx //= p
                e += 1
            exponents.append(e % 2)

        if Qx == 1:
            relations.append((x, exponents))

    return smooth_primes, relations

def find_nontrivial_dependency(relations, primes_number):
    relation_matrix = [r[1] for r in relations]

    for row, _ in enumerate(relation_matrix):
        pivot = row
        while pivot < primes_number and relation_matrix[row][pivot] == 0:
            pivot += 1

        if pivot < primes_number:
            relation_matrix[row], relation_matrix[pivot] = relation_matrix[pivot], relation_matrix[row]

            for rr in range(row + 1, len(relation_matrix)):
                if relation_matrix[rr][pivot] == 1:
                    for j in range(pivot, primes_number):
                        relation_matrix[rr][j] = (relation_matrix[rr][j] - relation_matrix[row][j]) % 2

            if row != primes_number - 1:
                relation_matrix = relation_matrix[:-1]

    used_relations = [r[0] for i, r in enumerate(relations) if relation_matrix[-1][i] == 1]
    return used_relations

def general_number_field_sieve(n):
    if n % 2 == 0:
        return 2

    base = int(sqrt(n)) + 1

    primes, relations = find_factor(base, n)
    used_relations = find_nontrivial_dependency(relations, len(primes))

    x_rel = (used_relations[0][0], used_relations[0][1].copy())
    for u_rel in used_relations[1:]:
        x_rel = (x_rel[0] * u_rel[0] % n, [(x + y) % 2 for x, y in zip(x_rel[1], u_rel[1])])

    x = x_rel[0]
    y = 1
    for p, e in zip(primes, x_rel[1]):
        if e == 1:
            y *= p
    y = pow(y, 2, n)

    factor = gcd(x - y, n)
    return factor

# Test the implementation
n = 15486451  # A large semiprime number
factor = general_number_field_sieve(n)
print("One factor of", n, "is:", factor)
```

This code is based on the Quadratic Sieve algorithm, which works well for moderately large numbers. However, it may not be sufficient for very large numbers typically used in cryptographic applications. For more efficient factorization of extremely large numbers, a full-fledged General Number Field Sieve implementation should be considered, but such an implementation is quite complex and beyond the scope of a simple answer in this format.

