To create a reactive website using Flask and JavaScript that allows a user to upload a file, view the file they uploaded, and then download the file again, you can follow these steps:

1. Install Flask via `pip`.

```bash
$ pip install Flask
```

2. Create a new folder called `upload_demo` and add a `static` directory and a `templates` directory.

```bash
$ mkdir upload_demo static templates
$ cd upload_demo
```

3. Create a Python file named `app.py` containing the following Flask code:

```python
from flask import Flask, render_template, request, send_from_directory
import os

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploaded_files'
app.config['ALLOWED_EXTENSIONS'] = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif', 'doc', 'docx', 'xlsx'}

# Function for allowed file extensions
def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload():
    file = request.files['file']

    if allowed_file(file.filename):
        filename = file.filename
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(filepath)
        return render_template('uploaded.html', filename=filename)
    else:
        return "File type not allowed", 400

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(os.path.join(app.config['UPLOAD_FOLDER']), filename, as_attachment=True)

@app.route('/download/<filename>')
def download(filename):
    try:
        return send_from_directory(os.path.join(app.config['UPLOAD_FOLDER']), filename, as_attachment=True)
    except Exception as e:
        return str(e)

if __name__ == '__main__':
    if not os.path.exists('uploaded_files'):
        os.makedirs('uploaded_files')

    app.run(debug=True)
```

